/**
 * Inventory Plugin — Database Layer
 *
 * SQL surface backing the field-app gate-entry flow. Distinct from the
 * legacy top-level `inventory` table, which stores LLM extractions from
 * chat messages — these tables persist the structured capture stream
 * (products, orders, receipts, stock, issues, reorder requests,
 * mismatch flags).
 *
 * Schema migration runs from `lib/postgres-schema.ts` via
 * `ensureOfficeOpsPostgresSchema()`, the same boot path the visitor
 * module uses. This file owns the CRUD only.
 */

import { getDb } from "../../lib/database";
import { ensureOfficeOpsPostgresSchema } from "../../lib/postgres";

export type InventoryProduct = {
  barcode: string;
  site_id: string;
  name: string;
  category: string | null;
  unit: string | null;
  pack_size: number | null;
  registered_by: string | null;
  created_at: string;
  updated_at: string;
};

export type InventoryOrder = {
  id: string;
  site_id: string;
  vendor: string | null;
  expected_at: string | null;
  arrived_at: string | null;
  status: string;
  created_at: string;
  updated_at: string;
};

export type InventoryOrderItem = {
  id: string;
  order_id: string;
  barcode: string | null;
  product_id: string | null;
  product_name: string;
  expected_qty: number;
  received_qty: number;
};

export type InventoryStockRow = {
  barcode: string;
  site_id: string;
  name: string;
  category: string | null;
  unit: string | null;
  on_hand: number;
  threshold: number;
  updated_at: string;
  pack_size: number | null;
};

export type InventoryReceipt = {
  id: string;
  site_id: string;
  order_id: string | null;
  order_item_id: string | null;
  barcode: string;
  product_name: string;
  qty: number;
  flagged: boolean;
  device_id: string | null;
  guard_id: string | null;
  scanned_at: string;
};

export async function initInventorySchema(): Promise<void> {
  await ensureOfficeOpsPostgresSchema();
}

// ─── Products ─────────────────────────────────────────────────────

export async function upsertProduct(input: {
  siteId: string;
  barcode: string;
  name: string;
  category?: string | null;
  unit?: string | null;
  packSize?: number | null;
  registeredBy?: string | null;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO inventory_products (barcode, site_id, name, category, unit, pack_size, registered_by)
      VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (site_id, barcode) DO UPDATE SET
        name = EXCLUDED.name,
        category = COALESCE(EXCLUDED.category, inventory_products.category),
        unit = COALESCE(EXCLUDED.unit, inventory_products.unit),
        pack_size = COALESCE(EXCLUDED.pack_size, inventory_products.pack_size),
        updated_at = now()
    `,
    args: [
      input.barcode,
      input.siteId,
      input.name,
      input.category ?? null,
      input.unit ?? null,
      input.packSize ?? null,
      input.registeredBy ?? null,
    ],
  });
}

export async function findProduct(
  siteId: string,
  barcode: string,
): Promise<InventoryProduct | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT * FROM inventory_products WHERE site_id = ? AND barcode = ? LIMIT 1`,
    args: [siteId, barcode],
  });
  return (result.rows[0] as InventoryProduct | undefined) ?? null;
}

// ─── Orders ───────────────────────────────────────────────────────

export async function listOpenOrders(siteId: string): Promise<InventoryOrder[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT * FROM inventory_orders WHERE site_id = ? AND status = 'open' ORDER BY expected_at ASC NULLS LAST`,
    args: [siteId],
  });
  return result.rows as InventoryOrder[];
}

export async function getOrderItems(orderId: string): Promise<InventoryOrderItem[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT * FROM inventory_order_items WHERE order_id = ?`,
    args: [orderId],
  });
  return result.rows as InventoryOrderItem[];
}

export async function findOpenItemByBarcode(
  siteId: string,
  barcode: string,
): Promise<InventoryOrderItem | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT oi.* FROM inventory_order_items oi
      JOIN inventory_orders o ON o.id = oi.order_id
      WHERE oi.barcode = ? AND o.site_id = ? AND o.status = 'open'
      ORDER BY o.expected_at ASC NULLS LAST
      LIMIT 1
    `,
    args: [barcode, siteId],
  });
  return (result.rows[0] as InventoryOrderItem | undefined) ?? null;
}

export async function addReceivedQty(itemId: string, delta: number): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `UPDATE inventory_order_items SET received_qty = received_qty + ? WHERE id = ?`,
    args: [delta, itemId],
  });
}

export async function markOrderArrived(orderId: string, when: string): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `UPDATE inventory_orders SET arrived_at = ?, updated_at = now() WHERE id = ? AND arrived_at IS NULL`,
    args: [when, orderId],
  });
}

// ─── Receipts ─────────────────────────────────────────────────────

/**
 * Idempotent on `id`. Field-app outbox retries land here without
 * double-counting because we ON CONFLICT DO NOTHING and report whether
 * the row was actually inserted.
 */
export async function insertReceipt(input: {
  id: string;
  siteId: string;
  orderId?: string | null;
  orderItemId?: string | null;
  productId?: string | null;
  barcode: string;
  productName: string;
  qty: number;
  expiryDate?: string | null;
  flagged?: boolean;
  deviceId?: string | null;
  guardId?: string | null;
  scannedAt: string;
}): Promise<{ inserted: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_receipts (
        id, site_id, order_id, order_item_id, product_id, barcode, product_name,
        qty, expiry_date, flagged, device_id, guard_id, scanned_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (id) DO NOTHING
    `,
    args: [
      input.id,
      input.siteId,
      input.orderId ?? null,
      input.orderItemId ?? null,
      input.productId ?? null,
      input.barcode,
      input.productName,
      input.qty,
      input.expiryDate ?? null,
      input.flagged ?? false,
      input.deviceId ?? null,
      input.guardId ?? null,
      input.scannedAt,
    ],
  });
  return { inserted: (result.rowsAffected ?? 0) > 0 };
}

export type ComplianceLogRow = {
  scanned_at: string;
  date: string;
  vendor: string | null;
  bill_number: string | null;
  product_id: string | null;
  product_name: string;
  bill_item_name: string | null;
  category: string | null;
  hsn_code: string | null;
  unit: string | null;
  pack_size: number | null;
  qty_received: number;
  expected_qty: number | null;
  unit_rate: number | null;
  line_value: number | null;
  expiry_date: string | null;
  received_by: string | null;
  status: 'OK' | 'Flagged';
};

export async function getComplianceLogForReceipt(
  siteId: string,
  receiptId: string,
): Promise<ComplianceLogRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT
        r.scanned_at,
        to_char(r.scanned_at, 'YYYY-MM-DD') AS date,
        io.vendor AS vendor,
        io.bill_number AS bill_number,
        COALESCE(r.product_id, oi.product_id) AS product_id,
        COALESCE(cp.canonical_name, r.product_name) AS product_name,
        oi.bill_item_name AS bill_item_name,
        cp.category AS category,
        COALESCE(cp.hsn_code, oi.hsn_code) AS hsn_code,
        cp.unit AS unit,
        cp.pack_size AS pack_size,
        r.qty AS qty_received,
        oi.expected_qty AS expected_qty,
        oi.unit_rate AS unit_rate,
        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
        r.expiry_date AS expiry_date,
        COALESCE(g.name, r.guard_id) AS received_by,
        -- Flagged = the guard explicitly raised a mismatch flag at the
        -- gate (qty mismatch, bad expiry). Pure qty vs expected was
        -- misleading for partial deliveries.
        -- (Historical note: this comment used to contain an apostrophe
        -- which broke the driver placeholder normalizer; see comments
        -- in lib/database.ts replaceQuestionPlaceholders for details.)
        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
      FROM inventory_receipts r
      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
      LEFT JOIN inventory_orders io ON io.id = r.order_id
      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
      LEFT JOIN guards g ON g.id = r.guard_id
      WHERE r.id = ? AND r.site_id = ?
      LIMIT 1
    `,
    args: [receiptId, siteId],
  });
  const row = (result.rows[0] as unknown as ComplianceLogRow | undefined) ?? null;
  return row;
}

export async function listComplianceLog(
  siteId: string,
  fromDate?: string | null,
  toDate?: string | null,
): Promise<ComplianceLogRow[]> {
  const db = await getDb();
  const conds: string[] = ['r.site_id = ?'];
  const args: (string | number | null)[] = [siteId];
  if (fromDate) { conds.push('r.scanned_at >= ?'); args.push(fromDate); }
  if (toDate) { conds.push('r.scanned_at <= ?'); args.push(toDate); }
  const result = await db.execute({
    sql: `
      SELECT
        r.scanned_at,
        to_char(r.scanned_at, 'YYYY-MM-DD') AS date,
        io.vendor AS vendor,
        io.bill_number AS bill_number,
        COALESCE(r.product_id, oi.product_id) AS product_id,
        COALESCE(cp.canonical_name, r.product_name) AS product_name,
        oi.bill_item_name AS bill_item_name,
        cp.category AS category,
        COALESCE(cp.hsn_code, oi.hsn_code) AS hsn_code,
        cp.unit AS unit,
        cp.pack_size AS pack_size,
        r.qty AS qty_received,
        oi.expected_qty AS expected_qty,
        oi.unit_rate AS unit_rate,
        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
        r.expiry_date AS expiry_date,
        COALESCE(g.name, r.guard_id) AS received_by,
        -- Flagged = guard explicitly raised a mismatch flag at the
        -- gate (qty mismatch, bad expiry, etc.). Pure qty vs expected
        -- was misleading for partial deliveries.
        --   IMPORTANT: no apostrophes in SQL comments here (see notes in
        --   getComplianceLogForReceipt above for the placeholder bug).
        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
      FROM inventory_receipts r
      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
      LEFT JOIN inventory_orders io ON io.id = r.order_id
      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
      LEFT JOIN guards g ON g.id = r.guard_id
      WHERE ${conds.join(' AND ')}
      ORDER BY r.scanned_at DESC
    `,
    args,
  });
  return result.rows as unknown as ComplianceLogRow[];
}

// ─── Stock ────────────────────────────────────────────────────────

// Pack size lives on canonical_products (or the older inventory_products
// fallback) — not on inventory_stock. Join so the field-app can render
// "{on_hand} × {pack_size} {unit}" instead of just "{on_hand} {unit}".
const STOCK_SELECT = `
  s.barcode, s.site_id, s.name, s.category, s.unit, s.on_hand, s.threshold, s.updated_at,
  COALESCE(cp.pack_size, ip.pack_size) AS pack_size
`;
const STOCK_JOINS = `
  FROM inventory_stock s
  LEFT JOIN product_barcodes pb ON pb.site_id = s.site_id AND pb.barcode = s.barcode
  LEFT JOIN canonical_products cp ON cp.product_id = pb.product_id
  LEFT JOIN inventory_products ip ON ip.site_id = s.site_id AND ip.barcode = s.barcode
`;

export async function listStock(siteId: string): Promise<InventoryStockRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT ${STOCK_SELECT} ${STOCK_JOINS} WHERE s.site_id = ? ORDER BY s.name`,
    args: [siteId],
  });
  return result.rows as InventoryStockRow[];
}

export async function listLowOrOut(siteId: string): Promise<InventoryStockRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_SELECT}
      ${STOCK_JOINS}
      WHERE s.site_id = ? AND s.on_hand <= s.threshold
      ORDER BY s.on_hand ASC, s.name ASC
    `,
    args: [siteId],
  });
  return result.rows as InventoryStockRow[];
}

