export type CanonicalProduct = {
  product_id: string;
  site_id: string;
  canonical_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string;
  pack_size: number;
  created_by: string | null;
  created_at: string;
  updated_at: string;
  /** True if any barcode is already mapped to this product. Populated by
   *  list queries; the field-app's register-new-barcode flow uses this to
   *  hide products that are already taken (one barcode per product, for
   *  now). Single-row lookups leave it undefined. */
  has_barcode?: boolean;
};

export async function upsertCanonicalProduct(input: {
  productId: string;
  siteId: string;
  canonicalName: string;
  category?: string | null;
  hsnCode?: string | null;
  unit: string;
  packSize?: number;
  createdBy?: string | null;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO canonical_products (product_id, site_id, canonical_name, category, hsn_code, unit, pack_size, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (product_id) DO UPDATE SET
        canonical_name = EXCLUDED.canonical_name,
        category = COALESCE(EXCLUDED.category, canonical_products.category),
        hsn_code = COALESCE(EXCLUDED.hsn_code, canonical_products.hsn_code),
        unit = EXCLUDED.unit,
        pack_size = EXCLUDED.pack_size,
        updated_at = now()
    `,
    args: [
      input.productId,
      input.siteId,
      input.canonicalName,
      input.category ?? null,
      input.hsnCode ?? null,
      input.unit,
      input.packSize ?? 1,
      input.createdBy ?? null,
    ],
  });
}

/** Direct UPDATE on canonical_products. Unlike upsertCanonicalProduct
 *  (which COALESCEs nullable fields into the existing row), passing
 *  `null` here actually clears category / hsn_code. Undefined fields
 *  are left untouched. Use this from the admin Catalog editor where
 *  blanking a field must persist. */
export async function updateCanonicalProduct(input: {
  productId: string;
  canonicalName?: string;
  category?: string | null;
  hsnCode?: string | null;
  unit?: string;
  packSize?: number;
}): Promise<{ updated: boolean }> {
  const db = await getDb();
  const sets: string[] = [];
  const args: (string | number | null)[] = [];
  if (input.canonicalName !== undefined) {
    sets.push(`canonical_name = ?`);
    args.push(input.canonicalName);
  }
  if (input.category !== undefined) {
    sets.push(`category = ?`);
    args.push(input.category);
  }
  if (input.hsnCode !== undefined) {
    sets.push(`hsn_code = ?`);
    args.push(input.hsnCode);
  }
  if (input.unit !== undefined) {
    sets.push(`unit = ?`);
    args.push(input.unit);
  }
  if (input.packSize !== undefined) {
    sets.push(`pack_size = ?`);
    args.push(input.packSize);
  }
  if (sets.length === 0) return { updated: false };
  sets.push(`updated_at = now()`);
  args.push(input.productId);
  const result = await db.execute({
    sql: `UPDATE canonical_products SET ${sets.join(", ")} WHERE product_id = ?`,
    args,
  });
  return { updated: (result.rowsAffected ?? 0) > 0 };
}

