/** Update raw_name / hsn_code on an existing alias. Undefined fields are
 *  left untouched; `hsn_code: null` explicitly clears the HSN. The
 *  (site_id, raw_name, COALESCE(hsn_code, '')) unique index can collide
 *  if the new combination already exists for the site — let Postgres
 *  raise 23505 and the route surface a clean error. */
export async function updateProductAlias(input: {
  id: string;
  rawName?: string;
  hsnCode?: string | null;
}): Promise<{ updated: boolean }> {
  const db = await getDb();
  const sets: string[] = [];
  const args: (string | null)[] = [];
  if (input.rawName !== undefined) {
    sets.push(`raw_name = lower(?)`);
    args.push(input.rawName.trim());
  }
  if (input.hsnCode !== undefined) {
    sets.push(`hsn_code = ?`);
    args.push(input.hsnCode);
  }
  if (sets.length === 0) return { updated: false };
  args.push(input.id);
  const result = await db.execute({
    sql: `UPDATE product_aliases SET ${sets.join(", ")} WHERE id = ?`,
    args,
  });
  return { updated: (result.rowsAffected ?? 0) > 0 };
}

