  const result = await db.execute({
    sql: `
      SELECT u.*, o.vendor, o.bill_number
      FROM unresolved_bill_items u
      LEFT JOIN inventory_orders o ON u.order_id = o.id
      WHERE u.site_id = ? AND u.status = 'pending'
      ORDER BY u.created_at DESC
