// ─── Extended Order Creation (Bill → Order) ──────────────────────

export async function createOrderFromBill(input: {
  id: string;
  siteId: string;
  vendor?: string | null;
  billNumber?: string | null;
  billDate?: string | null;
  billPhotoUrl?: string | null;
  grandTotal?: number | null;
  expectedAt?: string | null;
}): Promise<void> {
