      VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'open')
      ON CONFLICT (id) DO UPDATE SET
        vendor = COALESCE(EXCLUDED.vendor, inventory_orders.vendor),
        bill_number = COALESCE(EXCLUDED.bill_number, inventory_orders.bill_number),
        bill_date = COALESCE(EXCLUDED.bill_date, inventory_orders.bill_date),
