export type CatalogSheetRow = {
  canonical_name: string;
  category: string | null;
  unit: string;
  pack_size: number;
  last_price: number | null;
  barcodes: string | null; // comma-separated
  hsn_code: string | null;
};

export type StockSheetRow = {
  canonical_name: string;
  category: string | null;
  unit: string;
  pack_size: number;
  last_price: number | null;
  barcodes: string | null; // comma-separated
  on_hand: number;
  expiry_dates: string | null; // comma-separated YYYY-MM-DD, ascending
};

/**
 * Snapshot of the catalog for the Google Sheet "Catalog" tab. Joins
 * canonical_products → product_barcodes (concatenated) and pulls the
 * most recent unit_rate from inventory_order_items as a price proxy
 * (canonical products don't carry a price column today).
 */
export async function listCatalogForSheet(siteId: string): Promise<CatalogSheetRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT
        cp.canonical_name,
        cp.category,
        cp.unit,
        cp.pack_size,
        cp.hsn_code,
        (SELECT string_agg(pb.barcode, ', ')
           FROM product_barcodes pb
          WHERE pb.product_id = cp.product_id) AS barcodes,
        (SELECT oi.unit_rate
           FROM inventory_order_items oi
           JOIN inventory_orders o ON o.id = oi.order_id
          WHERE oi.product_id = cp.product_id AND o.site_id = ?
          ORDER BY o.created_at DESC
          LIMIT 1) AS last_price
      FROM canonical_products cp
      WHERE cp.site_id = ?
      ORDER BY cp.canonical_name
    `,
    args: [siteId, siteId],
  });
  return result.rows as unknown as CatalogSheetRow[];
}

/**
 * Snapshot of current stock for the Google Sheet "Stock" tab and the
 * dashboard Stock view. One row per canonical product that has an
 * inventory_stock entry; pulls the most recent unit_rate as price
 * (same source as Catalog) and aggregates distinct *future* expiry
 * dates from receipts (already-passed expiries are dropped — the
 * item is logically consumed/gone).
 */
export async function listStockForSheet(siteId: string): Promise<StockSheetRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT
        COALESCE(cp.canonical_name, s.name) AS canonical_name,
        COALESCE(cp.category, s.category)   AS category,
        COALESCE(cp.unit, s.unit, 'pcs')    AS unit,
        COALESCE(cp.pack_size, 1)           AS pack_size,
        (SELECT string_agg(pb2.barcode, ', ')
           FROM product_barcodes pb2
          WHERE pb2.site_id = s.site_id
            AND pb2.product_id = cp.product_id) AS barcodes,
        (SELECT oi.unit_rate
           FROM inventory_order_items oi
           JOIN inventory_orders o ON o.id = oi.order_id
          WHERE oi.product_id = cp.product_id AND o.site_id = ?
          ORDER BY o.created_at DESC
          LIMIT 1) AS last_price,
        s.on_hand AS on_hand,
        (SELECT string_agg(DISTINCT to_char(r.expiry_date, 'YYYY-MM-DD'), ', ' ORDER BY to_char(r.expiry_date, 'YYYY-MM-DD'))
           FROM inventory_receipts r
          WHERE r.site_id = s.site_id
            AND r.expiry_date IS NOT NULL
            AND r.expiry_date >= CURRENT_DATE
            AND (r.product_id = cp.product_id OR r.barcode = s.barcode)) AS expiry_dates
      FROM inventory_stock s
      LEFT JOIN product_barcodes pb ON pb.site_id = s.site_id AND pb.barcode = s.barcode
      LEFT JOIN canonical_products cp ON cp.product_id = pb.product_id
      WHERE s.site_id = ?
      ORDER BY canonical_name
    `,
    args: [siteId, siteId],
  });
  return result.rows as unknown as StockSheetRow[];
}

/**
 * Drop every learned alias for a site. Useful when the alias cache has
 * been poisoned by a prior run that auto-saved wrong mappings.
 */
export async function clearProductAliases(siteId: string): Promise<{ deleted: number }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `DELETE FROM product_aliases WHERE site_id = ?`,
    args: [siteId],
  });
  return { deleted: Number(result.rowsAffected ?? 0) };
}

// ─── Orders for dashboard (full listing with items) ─────────────

export type OrderWithItems = {
  id: string;
  site_id: string;
  vendor: string | null;
  bill_number: string | null;
  bill_date: string | null;
  grand_total: number | null;
  status: string;
  expected_at: string | null;
  arrived_at: string | null;
  created_at: string;
  items: Array<{
    id: string;
    order_id: string;
    product_id: string | null;
    product_name: string;
    bill_item_name: string | null;
    hsn_code: string | null;
    expected_qty: number;
    received_qty: number;
    unit_rate: number | null;
    line_value: number | null;
    unit: string | null;
    pack_size: number | null;
  }>;
};

export async function listOrdersWithItems(siteId: string): Promise<OrderWithItems[]> {
  const db = await getDb();
  const ordersRes = await db.execute({
    // bill_date is a DATE column — pg returns it as a JS Date which JSON-
    // serialises as a full ISO timestamp ("2026-06-03T00:00:00.000Z").
    // <input type="date"> silently rejects that, so the dashboard would
    // show an empty input on refresh even though the DB had the value.
    // Coerce to plain "YYYY-MM-DD" here.
    sql: `
      SELECT id, site_id, vendor, bill_number,
             to_char(bill_date, 'YYYY-MM-DD') AS bill_date,
             grand_total, status,
             expected_at, arrived_at, created_at
      FROM inventory_orders
      WHERE site_id = ?
      ORDER BY created_at DESC
    `,
    args: [siteId],
  });
  const orders = ordersRes.rows as Array<Omit<OrderWithItems, "items">>;
  if (orders.length === 0) return [];

  const itemsRes = await db.execute({
    sql: `
      SELECT oi.id, oi.order_id, oi.product_id, oi.product_name, oi.bill_item_name,
             oi.hsn_code, oi.expected_qty, oi.received_qty, oi.unit_rate, oi.line_value,
             cp.unit AS unit, cp.pack_size AS pack_size
      FROM inventory_order_items oi
      LEFT JOIN canonical_products cp ON cp.product_id = oi.product_id
      WHERE oi.order_id IN (${orders.map(() => "?").join(",")})
    `,
    args: orders.map((o) => o.id),
  });
  const itemsByOrder = new Map<string, OrderWithItems["items"]>();
  for (const row of itemsRes.rows as OrderWithItems["items"]) {
    const list = itemsByOrder.get(row.order_id) ?? [];
    list.push(row);
    itemsByOrder.set(row.order_id, list);
  }
  return orders.map((o) => ({ ...o, items: itemsByOrder.get(o.id) ?? [] }));
}

export async function deleteOrder(siteId: string, orderId: string): Promise<{ deleted: boolean }> {
  const db = await getDb();
  // Detach any receipts pointing at this order so the audit trail
  // survives but the FK doesn't block the delete. This works whether
  // or not the migration to ON DELETE SET NULL has run.
  await db.execute({
    sql: `UPDATE inventory_receipts SET order_item_id = NULL
          WHERE order_item_id IN (
            SELECT id FROM inventory_order_items WHERE order_id = ?
          )`,
    args: [orderId],
  });
  await db.execute({
    sql: `UPDATE inventory_receipts SET order_id = NULL WHERE order_id = ?`,
    args: [orderId],
  });
  await db.execute({
    sql: `UPDATE inventory_mismatch_flags SET order_item_id = NULL
          WHERE order_item_id IN (
            SELECT id FROM inventory_order_items WHERE order_id = ?
          )`,
    args: [orderId],
  });
  // ON DELETE CASCADE on inventory_order_items removes the items.
  const result = await db.execute({
    sql: `DELETE FROM inventory_orders WHERE id = ? AND site_id = ?`,
    args: [orderId, siteId],
  });
  return { deleted: (result.rowsAffected ?? 0) > 0 };
}

export async function updateOrderMeta(input: {
  orderId: string;
  siteId: string;
  vendor?: string | null;
  billNumber?: string | null;
  billDate?: string | null;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      UPDATE inventory_orders
      SET vendor = COALESCE(?, vendor),
          bill_number = COALESCE(?, bill_number),
          bill_date = COALESCE(?, bill_date),
          updated_at = now()
      WHERE id = ? AND site_id = ?
    `,
    args: [
      input.vendor ?? null,
      input.billNumber ?? null,
      input.billDate ?? null,
      input.orderId,
      input.siteId,
    ],
  });
}

export async function updateOrderItem(input: {
  itemId: string;
  productId?: string | null;
  productName?: string | null;
  hsnCode?: string | null;
  expectedQty?: number | null;
  unitRate?: number | null;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      UPDATE inventory_order_items
      SET product_id = COALESCE(?, product_id),
          product_name = COALESCE(?, product_name),
          hsn_code = COALESCE(?, hsn_code),
          expected_qty = COALESCE(?, expected_qty),
          unit_rate = COALESCE(?, unit_rate)
      WHERE id = ?
    `,
    args: [
      input.productId ?? null,
      input.productName ?? null,
      input.hsnCode ?? null,
      input.expectedQty ?? null,
      input.unitRate ?? null,
      input.itemId,
    ],
