export async function deleteOrderItem(itemId: string): Promise<{ deleted: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `DELETE FROM inventory_order_items WHERE id = ?`,
    args: [itemId],
  });
  return { deleted: (result.rowsAffected ?? 0) > 0 };
}

// ─── Site Settings (key-value) ───────────────────────────────────

// "key" is a SQL reserved-ish word — Postgres errored with "syntax error
// at or near AND" on `WHERE site_id = ? AND key = ?` because the parser
// interpreted the bareword `key` as a reserved token. Always quote it.
export async function getSetting(siteId: string, key: string): Promise<string | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT value FROM inventory_settings WHERE site_id = ? AND "key" = ?`,
    args: [siteId, key],
  });
  const row = result.rows[0] as { value: string | null } | undefined;
  return row?.value ?? null;
}

export async function setSetting(siteId: string, key: string, value: string): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO inventory_settings (site_id, "key", value, updated_at)
      VALUES (?, ?, ?, now())
      ON CONFLICT (site_id, "key") DO UPDATE SET
        value = excluded.value,
        updated_at = now()
    `,
    args: [siteId, key, value],
  });
}

export async function deleteSetting(siteId: string, key: string): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `DELETE FROM inventory_settings WHERE site_id = ? AND "key" = ?`,
    args: [siteId, key],
  });
}

