/**
 * Append a single row to a specific spreadsheet + tab using a caller-
 * supplied authenticated `sheets` client. The client must already be
 * authorized for `spreadsheetId` (e.g. built from an OAuth refresh
 * token via buildOAuthClientWithRefreshToken).
 */
export async function appendInventoryRow(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  tabName: string,
  headers: string[],
  rowData: string[],
): Promise<void> {
  await ensureSheet(sheets, spreadsheetId, tabName);

  try {
    const headerCheck = await sheets.spreadsheets.values.get({
      spreadsheetId,
      range: formatSheetRange(tabName, 'A1:A1'),
    });
    const hasHeaders = (headerCheck.data.values?.[0]?.length ?? 0) > 0;
    if (!hasHeaders) {
      await sheets.spreadsheets.values.update({
        spreadsheetId,
        range: formatSheetRange(tabName, 'A1'),
        valueInputOption: 'USER_ENTERED',
        requestBody: { values: [headers] },
      });
    }
  } catch {
    // non-critical
  }

  await sheets.spreadsheets.values.append({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A:A'),
    valueInputOption: 'USER_ENTERED',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: [rowData] },
  });

  // Apply date/time column formats AFTER the append so that the newly
  // inserted row (created by INSERT_ROWS) gets the correct format.
  await ensureInventoryDateColumnFormats(sheets, spreadsheetId, tabName, headers);
}

// Sheets' USER_ENTERED parses "2026-06-03" → date serial 46176, then
// renders it using whatever number format the column already had. On
// older tabs that defaulted to "Number", that produces "46176" instead
// of a date — the bug we hit on Ordered/Received.
//
// This runs AFTER every append (not before) because INSERT_ROWS creates
// a brand-new row whose cells start with no format. RepeatCell then
// stamps the correct date/time format onto all data rows including the
// freshly inserted one. No per-process cache — we always reapply so
// that both old and new rows are guaranteed to render correctly.
async function ensureInventoryDateColumnFormats(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  tabName: string,
  headers: string[],
): Promise<void> {

  try {
    const meta = await sheets.spreadsheets.get({ spreadsheetId });
    const sheet = meta.data.sheets?.find((s) => s.properties?.title === tabName);
    const sheetId = sheet?.properties?.sheetId;
    if (sheetId == null) return;

    const dateColumns: string[] = ['Bill Date', 'Date', 'Expiry'];
    const timeColumns: string[] = ['Time (IST)'];

    const requests: sheets_v4.Schema$Request[] = [];
    const addFormat = (col: number, pattern: string, type: 'DATE' | 'TIME') => {
      requests.push({
        repeatCell: {
          range: {
            sheetId,
            startRowIndex: 1,
            startColumnIndex: col,
            endColumnIndex: col + 1,
          },
          cell: { userEnteredFormat: { numberFormat: { type, pattern } } },
          fields: 'userEnteredFormat.numberFormat',
        },
      });
    };

    for (const name of dateColumns) {
      const idx = headers.indexOf(name);
      if (idx >= 0) addFormat(idx, 'dd-mmm-yyyy', 'DATE');
    }
    for (const name of timeColumns) {
      const idx = headers.indexOf(name);
      if (idx >= 0) addFormat(idx, 'hh:mm:ss', 'TIME');
    }

    if (requests.length > 0) {
      await sheets.spreadsheets.batchUpdate({ spreadsheetId, requestBody: { requests } });
    }
  } catch {
    // Non-critical: a missing format just means the column may still
    // render as a serial. We don't want to block the write.
  }
}

/**
 * Replace every row in a tab (clear → headers → values). For snapshot
 * sheets like Catalog that should reflect the current DB state rather
 * than accumulate history. Auto-creates the tab if missing.
 */
export async function replaceSheetTab(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  tabName: string,
  headers: string[],
  rows: string[][],
): Promise<void> {
  await ensureSheet(sheets, spreadsheetId, tabName);
  await sheets.spreadsheets.values.clear({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A:Z'),
  });
  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range: formatSheetRange(tabName, 'A1'),
    valueInputOption: 'USER_ENTERED',
    requestBody: { values: [headers, ...rows] },
  });
}

/**
 * Verify the supplied sheets client can read a spreadsheet — used by
 * the dashboard "Attach" button to confirm the URL is valid before
 * saving the id.
 */
export async function verifySpreadsheetAccess(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
): Promise<{ ok: boolean; title?: string; error?: string }> {
  try {
    const meta = await sheets.spreadsheets.get({ spreadsheetId });
    return { ok: true, title: meta.data.properties?.title ?? undefined };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

export const INVENTORY_SHEET_HEADERS = {
  Ordered: INVENTORY_ORDERED_HEADERS,
  Received: INVENTORY_RECEIVED_HEADERS,
  Catalog: INVENTORY_CATALOG_HEADERS,
  Stock: INVENTORY_STOCK_HEADERS,
};

// ─── Helpers ──────────────────────────────────────────────

/**
 * Build a Telegram deep-link URL from chat ID and message ID.
 */
function buildTelegramLink(chatId: unknown, msgId: unknown): string {
  if (!chatId || !msgId) return '';
  const absId = Math.abs(Number(chatId));
  const idStr = String(absId);
  const cleanId = idStr.startsWith('100') && idStr.length > 10 ? idStr.slice(3) : idStr;
  return `https://t.me/c/${cleanId}/${msgId}`;
}

function formatSheetRange(sheetTitle: string, range: string): string {
  const escapedTitle = sheetTitle.replace(/'/g, "''");
  return `'${escapedTitle}'!${range}`;
}

function formatHostResponse(value: unknown): string {
  return {
    coming: 'Coming',
    '5min': '5 min',
    not_expecting: 'Not expecting',
  }[String(value ?? '')] ?? '';
}

function colIndexToLetter(index: number): string {
  let result = '';
  let n = index;
  do {
    result = String.fromCharCode(65 + (n % 26)) + result;
    n = Math.floor(n / 26) - 1;
  } while (n >= 0);
  return result;
}

function normalizeHeader(value: unknown): string {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function getRowValue(
  row: string[],
  headerIndex: Map<string, number>,
  aliases: string[],
): string {
  for (const alias of aliases) {
    const index = headerIndex.get(alias);
    if (index !== undefined) {
      return String(row[index] ?? '').trim();
    }
  }
  return '';
}

