// ─── Stock Corrections (Edit Stock audit) ────────────────────────

export type StockCorrectionRow = {
  id: string;
  site_id: string;
  barcode: string;
  product_name: string;
  old_qty: number | null;
  new_qty: number;
  old_expiry: string | null;
  new_expiry: string | null;
  device_id: string | null;
  guard_id: string | null;
  guard_name: string | null;
  corrected_at: string;
  created_at: string;
};

export async function insertStockCorrection(input: {
  id: string;
  siteId: string;
  barcode: string;
  productName: string;
  oldQty: number | null;
  newQty: number;
  oldExpiry?: string | null;
  newExpiry?: string | null;
  deviceId?: string | null;
  guardId?: string | null;
  guardName?: string | null;
  correctedAt: string;
}): Promise<{ inserted: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_stock_corrections (
        id, site_id, barcode, product_name, old_qty, new_qty,
        old_expiry, new_expiry, device_id, guard_id, guard_name, corrected_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (id) DO NOTHING
    `,
    args: [
      input.id,
      input.siteId,
      input.barcode,
      input.productName,
      input.oldQty,
      input.newQty,
      input.oldExpiry ?? null,
      input.newExpiry ?? null,
      input.deviceId ?? null,
      input.guardId ?? null,
      input.guardName ?? null,
      input.correctedAt,
    ],
  });
  return { inserted: (result.rowsAffected ?? 0) > 0 };
}

export async function getStockCorrection(
  siteId: string,
  id: string,
): Promise<StockCorrectionRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT id, site_id, barcode, product_name, old_qty, new_qty,
             to_char(old_expiry, 'YYYY-MM-DD') AS old_expiry,
             to_char(new_expiry, 'YYYY-MM-DD') AS new_expiry,
             device_id, guard_id, guard_name, corrected_at, created_at
      FROM inventory_stock_corrections
      WHERE site_id = ? AND id = ?
      LIMIT 1
    `,
    args: [siteId, id],
  });
  return (result.rows[0] as StockCorrectionRow | undefined) ?? null;
}

export async function listStockCorrections(
  siteId: string,
): Promise<StockCorrectionRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT id, site_id, barcode, product_name, old_qty, new_qty,
             to_char(old_expiry, 'YYYY-MM-DD') AS old_expiry,
             to_char(new_expiry, 'YYYY-MM-DD') AS new_expiry,
             device_id, guard_id, guard_name, corrected_at, created_at
      FROM inventory_stock_corrections
      WHERE site_id = ?
      ORDER BY corrected_at DESC
    `,
    args: [siteId],
  });
  return result.rows as StockCorrectionRow[];
}

/**
 * Apply a correction directly to inventory_stock. Sets on_hand to the
 * absolute new value (not a delta) so the result on the server matches
 * what the guard saw and confirmed in the field-app.
 */
export async function setStockOnHand(input: {
  siteId: string;
  barcode: string;
  onHand: number;
  fallbackName?: string;
  fallbackCategory?: string | null;
  fallbackUnit?: string | null;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO inventory_stock (barcode, site_id, name, category, unit, on_hand, threshold)
      VALUES (?, ?, ?, ?, ?, GREATEST(?, 0), 0)
      ON CONFLICT (site_id, barcode) DO UPDATE SET
        on_hand = GREATEST(?, 0),
        updated_at = now()
    `,
    args: [
      input.barcode,
      input.siteId,
      input.fallbackName ?? "Unknown",
      input.fallbackCategory ?? null,
      input.fallbackUnit ?? null,
      input.onHand,
      input.onHand,
    ],
  });
}

