  const barcode = asString(body.barcode);
  const newQty = asNumber(body.new_qty);
  if (!id || !barcode || newQty === null) {
    const missing: string[] = [];
    if (!id) missing.push("id");
    if (!barcode) missing.push("barcode");
    if (newQty === null) missing.push("new_qty (numeric)");
    badRequest(res, `Cannot record stock correction — missing or invalid: ${missing.join(", ")}`);
    return true;
  }

  const productName = asString(body.product_name) ?? "Unknown";
  const newExpiry = asString(body.new_expiry);
  const result = await insertStockCorrection({
    id,
    siteId: auth.siteId,
    barcode,
    productName,
    oldQty: asNumber(body.old_qty),
    newQty,
    oldExpiry: asString(body.old_expiry),
    newExpiry,
    deviceId: auth.deviceId,
    guardId: auth.guardId,
    guardName: auth.guardName,
    correctedAt: isoOrNow(body.corrected_at),
  });

  if (result.inserted) {
    await setStockOnHand({
      siteId: auth.siteId,
      barcode,
      onHand: newQty,
      fallbackName: productName,
    });
    void appendCorrectionRowToSheet(auth.siteId, id).catch((err) => {
