/**
 * Append a single stock-correction row to the "Corrections" tab on the
 * linked sheet. Append-only audit — never replaces. Silently skips if no
 * sheet is attached, the row vanished from the DB, or the owner has no
 * Google token.
 */
async function appendCorrectionRowToSheet(
  siteId: string,
  correctionId: string,
): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return;
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return;
  const row = await getStockCorrection(siteId, correctionId);
  if (!row) return;
  const correctedAt = row.corrected_at ? new Date(row.corrected_at) : new Date();
  const oldQty = row.old_qty != null ? Number(row.old_qty) : null;
  const newQty = Number(row.new_qty);
  const delta = oldQty != null ? newQty - oldQty : null;
  await appendInventoryRow(
    sheets,
    spreadsheetId,
    "Corrections",
    INVENTORY_SHEET_HEADERS.Corrections,
    [
      formatShortDateInIST(correctedAt),
      formatTimeInIST(correctedAt),
      row.product_name,
      row.barcode,
      oldQty != null ? String(oldQty) : "",
      String(newQty),
      delta != null ? (delta > 0 ? `+${delta}` : String(delta)) : "",
      row.old_expiry ?? "",
      row.new_expiry ?? "",
      row.guard_name ?? row.guard_id ?? "",
    ],
  );
}

