// ───────────────────────── History (stock corrections) ─────────────────────────

function HistoryTab() {
  const correctionsQuery = useQuery({
    queryKey: ["inv-corrections"],
    queryFn: listStockCorrections,
    staleTime: 30_000,
  });
  const rows: StockCorrectionRow[] = correctionsQuery.data?.data?.corrections ?? [];
  const [filter, setFilter] = useState("");

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter(
      (r) =>
        r.product_name.toLowerCase().includes(q) ||
        r.barcode.toLowerCase().includes(q) ||
        (r.guard_name ?? "").toLowerCase().includes(q),
    );
  }, [rows, filter]);

  const fmtQty = (v: number | null) => (v == null ? "—" : String(v));
  const fmtDelta = (oldQ: number | null, newQ: number) => {
    if (oldQ == null) return "—";
    const d = newQ - oldQ;
    if (d === 0) return "0";
    return d > 0 ? `+${d}` : String(d);
  };
  const fmtDate = (v: string | null) => (v ? v : "—");
  const fmtWhen = (iso: string) => {
    try {
      const d = new Date(iso);
      return d.toLocaleString();
    } catch {
      return iso;
    }
  };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
        <input
          type="text"
          placeholder="Filter by product, barcode, or guard…"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ ...input, flex: 1, maxWidth: 360 }}
        />
        <button type="button" onClick={() => void correctionsQuery.refetch()} style={ghostBtn}>
          <RefreshCw size={14} /> Refresh
        </button>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={th}>When</th>
              <th style={th}>Product</th>
              <th style={th}>Barcode</th>
              <th style={th}>Old qty</th>
              <th style={th}>New qty</th>
              <th style={th}>Δ</th>
              <th style={th}>Old expiry</th>
              <th style={th}>New expiry</th>
              <th style={th}>By</th>
            </tr>
          </thead>
          <tbody>
            {correctionsQuery.isLoading && (
              <tr>
                <td style={td} colSpan={9}>Loading…</td>
              </tr>
            )}
            {!correctionsQuery.isLoading && filtered.length === 0 && (
              <tr>
                <td style={{ ...td, color: "var(--muted)" }} colSpan={9}>
                  No stock corrections yet. Edits made from the field-app's Stock screen appear here.
                </td>
              </tr>
            )}
            {filtered.map((r) => (
              <tr key={r.id} style={{ borderTop: "1px solid var(--line)" }}>
                <td style={td}>{fmtWhen(r.corrected_at)}</td>
                <td style={td}>{r.product_name}</td>
                <td style={{ ...td, fontFamily: "monospace", fontSize: 12 }}>{r.barcode}</td>
                <td style={td}>{fmtQty(r.old_qty)}</td>
                <td style={td}>{fmtQty(r.new_qty)}</td>
                <td style={td}>{fmtDelta(r.old_qty, r.new_qty)}</td>
                <td style={td}>{fmtDate(r.old_expiry)}</td>
                <td style={td}>{fmtDate(r.new_expiry)}</td>
                <td style={td}>{r.guard_name ?? r.guard_id ?? "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

