                onPress={() => { setPerPackExpiry((v) => !v); haptic.tap(); }}
                style={[styles.noExpiryRow, { marginTop: spacing.sm }]}
              >
                <View
                  style={[
                    styles.checkbox,
                    {
                      backgroundColor: perPackExpiry ? palette.primary : 'transparent',
