                    color={expiryDateObj ? palette.onSurface : palette.onSurfaceVariant}
                    style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
                  >
                    {expiryDateObj ? formatForDisplay(toISO(expiryDateObj)) : t('tapToSelectDate')}
                  </Text>
