                  <Pressable
                    key={i}
                    onPress={() => { setEditingPackIdx(i); setShowPicker(true); }}
                    style={[
                      styles.expiryInput,
                      {
                        backgroundColor: palette.surfaceContainerLowest,
                        borderColor: palette.outlineVariant,
                        flexDirection: 'row',
