export type StockCorrectionRow = {
  id: string;
  site_id: string;
  barcode: string;
  product_name: string;
  old_qty: number | null;
  new_qty: number;
  old_expiry: string | null;
  new_expiry: string | null;
  /** Comma-separated list of per-pack expiry ISO dates (read shape). */
  new_expiries: string | null;
  device_id: string | null;
  guard_id: string | null;
  guard_name: string | null;
  corrected_at: string;
  created_at: string;
};

export async function insertStockCorrection(input: {
  id: string;
  siteId: string;
  barcode: string;
  productName: string;
  oldQty: number | null;
  newQty: number;
  oldExpiry?: string | null;
  newExpiry?: string | null;
  /** Per-pack expiry dates when the guard turned on "different per pack". */
  newExpiries?: string[] | null;
  deviceId?: string | null;
  guardId?: string | null;
  guardName?: string | null;
  correctedAt: string;
}): Promise<{ inserted: boolean }> {
  const db = await getDb();
  // Postgres DATE[] literal: '{2026-01-01,2026-02-15}'. The libsql/pg shim
  // doesn't auto-box arrays so we hand-encode. Empty array → NULL.
  const expiriesLiteral =
    input.newExpiries && input.newExpiries.length > 0
      ? `{${input.newExpiries.map((d) => `"${d.replace(/"/g, '')}"`).join(",")}}`
      : null;
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_stock_corrections (
        id, site_id, barcode, product_name, old_qty, new_qty,
        old_expiry, new_expiry, new_expiries,
        device_id, guard_id, guard_name, corrected_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?::DATE[], ?, ?, ?, ?)
      ON CONFLICT (id) DO NOTHING
    `,
    args: [
      input.id,
      input.siteId,
      input.barcode,
      input.productName,
      input.oldQty,
      input.newQty,
      input.oldExpiry ?? null,
      input.newExpiry ?? null,
      expiriesLiteral,
      input.deviceId ?? null,
      input.guardId ?? null,
      input.guardName ?? null,
      input.correctedAt,
    ],
  });
  return { inserted: (result.rowsAffected ?? 0) > 0 };
}

// SELECT shape: render new_expiries as a comma-separated string so the
// driver layer doesn't have to handle array unmarshalling.
const STOCK_CORRECTION_SELECT = `
  id, site_id, barcode, product_name, old_qty, new_qty,
  to_char(old_expiry, 'YYYY-MM-DD') AS old_expiry,
  to_char(new_expiry, 'YYYY-MM-DD') AS new_expiry,
  (
    SELECT string_agg(to_char(d, 'YYYY-MM-DD'), ', ' ORDER BY d)
    FROM unnest(new_expiries) AS d
  ) AS new_expiries,
  device_id, guard_id, guard_name, corrected_at, created_at
`;

export async function getStockCorrection(
  siteId: string,
  id: string,
): Promise<StockCorrectionRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_CORRECTION_SELECT}
      FROM inventory_stock_corrections
      WHERE site_id = ? AND id = ?
      LIMIT 1
    `,
    args: [siteId, id],
  });
  return (result.rows[0] as StockCorrectionRow | undefined) ?? null;
}

export async function listStockCorrections(
  siteId: string,
): Promise<StockCorrectionRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_CORRECTION_SELECT}
      FROM inventory_stock_corrections
      WHERE site_id = ?
      ORDER BY corrected_at DESC
    `,
    args: [siteId],
  });
  return result.rows as StockCorrectionRow[];
}

