165	    // Learn barcode → product the moment the guard picks, so a future
166	    // scan auto-resolves even if they cancel the receipt downstream.
167	    if (incomingBarcode) {
168	      try {
169	        await learnBarcode(incomingBarcode, product.product_id, 'scan');
170	        await enqueue('learn_barcode', {
171	          barcode: incomingBarcode,
172	          product_id: product.product_id,
173	        }).catch(() => {});
174	      } catch {
175	        // Non-fatal: the receipt flow has its own learning step.
176	      }
177	    }
178	    // No-barcode pick path: if this product already has a real barcode
179	    // learned, reuse it so the receipt rolls into the same stock row and
180	    // the user sees the actual barcode (not `catalog_…`). Only fall back
181	    // to the synthetic id when nothing is mapped yet — the format is
182	    // stable per product_id so a later real-barcode learn keeps history
183	    // and stock aligned.
184	    let barcode = incomingBarcode;
185	    if (!barcode) {
186	      const existing = await findBarcodeForProduct(product.product_id);
187	      barcode = existing ?? `catalog_${product.product_id}`;
188	    }
189	    navigation.push('Receiving', {
190	      barcode,
191	      productId: product.product_id,
192	      productName: product.canonical_name,
193	      unit: product.unit,
194	      packSize: product.pack_size,
195	    });
196	  }
197	
198	  return (
199	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
200	      <AppBar
201	          title={t('pickProduct')}
202	          subtitle={`${products.length} ${products.length === 1 ? t('itemInCatalog') : t('itemsInCatalog')}`}
203	          onBack={() => navigation.goBack()}
204	          trailing={(() => {
205	            const s = getLastCatalogSync();
206	            const stale =
207	              s.error != null ||
208	              (s.remote > 0 && s.written !== s.remote);
209	            return <SyncRefreshButton onPress={refresh} stale={stale} />;
210	          })()}
211	        />
212	
213	      <KeyboardAvoidingView
214	        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
215	        style={{ flex: 1 }}
216	      >
217	      <View style={{ padding: spacing.md }}>
218	        <View
219	          style={{
220	            flexDirection: 'row',
221	            alignItems: 'center',
222	            gap: spacing.sm,
223	            paddingHorizontal: spacing.md,
224	            borderRadius: radius.md,
225	            backgroundColor: palette.surfaceContainerLowest,
226	            borderWidth: 1,
227	            borderColor: palette.outlineVariant,
228	          }}
229	        >
230	          <Search size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
231	          <TextInput
232	            value={query}
233	            onChangeText={setQuery}
234	            placeholder={t('searchPlaceholder')}
235	            placeholderTextColor={palette.onSurfaceVariant}
236	            style={{ flex: 1, paddingVertical: spacing.md, color: palette.onSurface, fontSize: 15 }}
237	            autoCorrect={false}
238	            autoCapitalize="none"
