243	              <X size={18} color={palette.onSurfaceVariant} strokeWidth={2.2} />
244	            </Pressable>
245	          )}
246	        </View>
247	      </View>
248	
249	      {loading ? (
250	        <View style={{ paddingHorizontal: spacing.md, gap: spacing.sm }}>
251	          <Skeleton height={48} />
252	          <Skeleton height={48} />
253	          <Skeleton height={48} />
254	        </View>
255	      ) : (
256	        <View style={{ flex: 1, paddingHorizontal: spacing.md, paddingBottom: spacing.xl }}>
257	          {/* Dropdown panel: single bordered surface, internally scrollable */}
258	          <View
259	            style={{
260	              flex: 1,
261	              borderWidth: 1,
262	              borderColor: palette.outlineVariant,
263	              borderRadius: radius.md,
264	              backgroundColor: palette.surface,
265	              overflow: 'hidden',
266	            }}
267	          >
268	            <FlatList
269	              data={visible}
270	              keyExtractor={(p) => p.product_id}
