/**
 * Backend client for the office-ops inventory plugin.
 *
 * Every request:
 *   - is prefixed with `${config.apiBaseUrl}/api/inventory/...`
 *   - carries `x-guard-token` (from session) and `x-site-id` / `x-device-id`
 *   - throws an `ApiError` with status + body on non-2xx
 *
 * The outbox flusher (syncService) calls `api.send.*`; screens call
 * `api.fetch.*`. When no session token is present, requests still go out
 * — the server replies 401 and the outbox keeps the row queued (or
 * the read screens fall back to local cache).
 */

import { config } from '../config';
import { getSession } from '../auth/session';
import { getDeviceId } from '../utils/device';

export class ApiError extends Error {
  constructor(public status: number, message: string, public body?: string) {
    super(message);
  }
  /** Friendly composite for surfaces that only see `err.message` — e.g.
   *  the outbox's `last_error` column. Pulls the server's
   *  `{ error: "..." }` body when present so the guard sees a real
   *  reason instead of just "HTTP 500". */
  static format(status: number, path: string, body: string | undefined): string {
    if (body) {
      try {
        const parsed = JSON.parse(body);
        if (parsed && typeof parsed.error === 'string') {
          return `HTTP ${status} on ${path} — ${parsed.error}`;
        }
      } catch {
        // not JSON, fall through
      }
      const trimmed = body.trim();
      if (trimmed.length > 0) {
        return `HTTP ${status} on ${path} — ${trimmed.slice(0, 180)}`;
      }
    }
    return `HTTP ${status} on ${path}`;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const deviceId = await getDeviceId();
  const session = getSession();
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Device-Id': deviceId,
    'X-Site-Id': config.siteId,
    ...((init?.headers as Record<string, string>) ?? {}),
  };
  if (session?.token) headers['X-Guard-Token'] = session.token;

  const res = await fetch(`${config.apiBaseUrl}${path}`, { ...init, headers });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    const body = text.slice(0, 500);
    throw new ApiError(res.status, ApiError.format(res.status, path, body), body);
  }
  return res.json() as Promise<T>;
}

const post = (path: string, payload: unknown) =>
  request<{ inserted?: boolean; id?: string; barcode?: string }>(path, {
    method: 'POST',
    body: JSON.stringify(payload),
  });

export type RemoteOrderItem = {
  id: string;
  order_id: string;
  barcode: string | null;
  product_id: string | null;
  product_name: string;
  expected_qty: number;
  received_qty: number;
};

export type RemoteOrder = {
  id: string;
  site_id: string;
  vendor: string | null;
  expected_at: string | null;
  arrived_at: string | null;
  status: string;
  items: RemoteOrderItem[];
};

export type RemoteStockRow = {
  barcode: string;
  site_id: string;
  name: string;
  category: string | null;
  unit: string | null;
  on_hand: number;
  threshold: number;
  pack_size: number | null;
};

export type RemoteProduct = {
  barcode: string;
  site_id: string;
  name: string;
  category: string | null;
  unit: string | null;
  pack_size: number | null;
};

export type RemoteCatalogHit = {
  product: RemoteProduct | null;
  openOrderItem: RemoteOrderItem | null;
};

export type RemoteCanonicalProduct = {
  product_id: string;
  site_id: string;
  canonical_name: string;
  category: string | null;
  hsn_code: string | null;
  unit: string;
  pack_size: number;
  created_at: string;
  updated_at: string;
  /** True iff at least one barcode is mapped to this product server-side.
   *  Drives the "hide already-taken products" filter when registering a
   *  brand-new barcode on the field-app. */
  has_barcode?: boolean;
};

export const api = {
  // Login is handled by visitor's guard auth endpoint, not the inventory
  // plugin. Lives here so screens have one client to import.
  async login(input: { guardName: string; pin: string }): Promise<{
    token: string;
    guardId: string;
    guardName: string;
    language: 'hindi' | 'english';
  }> {
    const deviceId = await getDeviceId();
    const res = await fetch(`${config.apiBaseUrl}/api/guard/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        guardName: input.guardName,
        pin: input.pin,
        deviceId,
        deviceName: 'field-app',
      }),
    });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      // Pull the server's reason out of `{ "error": "..." }` if present so
      // the LoginScreen shows something actionable instead of just "Login failed".
      let reason = text.slice(0, 200);
      try {
        const parsed = JSON.parse(text);
        if (parsed && typeof parsed.error === 'string') reason = parsed.error;
      } catch {}
      throw new ApiError(res.status, reason || `Login failed (${res.status})`, text.slice(0, 500));
    }
    return res.json();
  },

  // Writes (outbox-dispatched).
  send: {
    receipt: (payload: object) => post('/api/inventory/receipts', payload),
    product: (payload: object) => post('/api/inventory/products', payload),
    issue: (payload: object) => post('/api/inventory/issues', payload),
    reorderRequest: (payload: object) =>
      post('/api/inventory/reorder-requests', payload),
    mismatchFlag: (payload: object) =>
      post('/api/inventory/mismatch-flags', payload),
    learnBarcode: (payload: object) =>
      post('/api/inventory/canonical-products/learn-barcode', payload),
    stockCorrection: (payload: object) =>
      post('/api/inventory/corrections', payload),
  },

  // Reads (called by screens).
  fetch: {
    orders: () =>
      request<{ orders: RemoteOrder[] }>('/api/inventory/orders').then((r) => r.orders),
    stock: () =>
      request<{ stock: RemoteStockRow[] }>('/api/inventory/stock').then((r) => r.stock),
    alerts: () =>
      request<{ alerts: RemoteStockRow[] }>('/api/inventory/alerts').then((r) => r.alerts),
    catalog: (barcode: string) =>
      request<RemoteCatalogHit>(
        `/api/inventory/catalog/${encodeURIComponent(barcode)}`,
      ),
    normalizeName: (rawName: string) =>
      request<{
        canonical: string;
        language: 'en' | 'hi' | 'hinglish' | 'unknown';
        confidence: number;
        cached: boolean;
      }>('/api/inventory/products/normalize', {
        method: 'POST',
        body: JSON.stringify({ rawName }),
      }),
    canonicalProducts: () =>
      request<{ products: RemoteCanonicalProduct[] }>(
        '/api/inventory/canonical-products',
      ).then((r) => r.products),
  },
};

import * as SQLite from 'expo-sqlite';

let dbInstance: SQLite.SQLiteDatabase | null = null;

/**
 * Current schema version. Bump this and add a migration block in
 * `runMigrations()` whenever you need additive schema changes.
 */
const SCHEMA_VERSION = 6;

export async function getDb(): Promise<SQLite.SQLiteDatabase> {
  if (dbInstance) return dbInstance;
  const db = await SQLite.openDatabaseAsync('fieldapp.db');
  await db.execAsync(`
    PRAGMA journal_mode = WAL;
    PRAGMA foreign_keys = ON;

    CREATE TABLE IF NOT EXISTS products (
      barcode TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      category TEXT,
      unit TEXT,
      pack_size REAL,
      updated_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS orders (
      id TEXT PRIMARY KEY,
      vendor TEXT,
      expected_at INTEGER,
      status TEXT NOT NULL DEFAULT 'open',
      updated_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS order_items (
      id TEXT PRIMARY KEY,
      order_id TEXT NOT NULL,
      barcode TEXT,
      product_name TEXT NOT NULL,
      expected_qty REAL NOT NULL,
      received_qty REAL NOT NULL DEFAULT 0,
      FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS receipts (
      id TEXT PRIMARY KEY,
      order_id TEXT,
      barcode TEXT NOT NULL,
      product_name TEXT NOT NULL,
      qty REAL NOT NULL,
      scanned_at INTEGER NOT NULL,
      note TEXT
    );

    CREATE TABLE IF NOT EXISTS outbox (
      id TEXT PRIMARY KEY,
      kind TEXT NOT NULL,
      payload TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'queued',
      attempts INTEGER NOT NULL DEFAULT 0,
      last_error TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_outbox_status ON outbox(status);
    CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);

    CREATE TABLE IF NOT EXISTS stock_levels (
      barcode TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      category TEXT,
      unit TEXT,
      pack_size REAL,
      on_hand REAL NOT NULL DEFAULT 0,
      threshold REAL NOT NULL DEFAULT 0,
      updated_at INTEGER NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_stock_category ON stock_levels(category);
  `);

  await runMigrations(db);
  dbInstance = db;
  return db;
}

/**
 * Forward-only migrations keyed by PRAGMA user_version. Each migration
 * runs once; version is bumped after success. ALTER TABLE ADD COLUMN is
 * idempotent in SQLite (errors if column exists), so we guard with the
 * version check rather than catching errors.
 */
async function runMigrations(db: SQLite.SQLiteDatabase): Promise<void> {
  const row = await db.getFirstAsync<{ user_version: number }>(
    'PRAGMA user_version',
  );
  let version = row?.user_version ?? 0;

  if (version < 1) {
    await db.execAsync(`
      -- Per-scan expiry and audit columns on receipts
      ALTER TABLE receipts ADD COLUMN expiry_date TEXT;
      ALTER TABLE receipts ADD COLUMN performed_by TEXT;
      ALTER TABLE receipts ADD COLUMN performed_by_name TEXT;

      -- Audit trail table
      CREATE TABLE IF NOT EXISTS activity_log (
        id TEXT PRIMARY KEY,
        action TEXT NOT NULL,
        barcode TEXT,
        qty REAL,
        expiry_date TEXT,
        performed_by TEXT,
        performed_by_name TEXT,
        performed_at INTEGER NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_activity_action ON activity_log(action);
      CREATE INDEX IF NOT EXISTS idx_activity_barcode ON activity_log(barcode);

      PRAGMA user_version = 1;
    `);
    version = 1;
  }

  // Future migrations go here:
  // if (version < 3) { ... PRAGMA user_version = 3; }

  if (version < 2) {
    await db.execAsync(`
      -- Track nearest expiry per stock item for quick alert queries
      ALTER TABLE stock_levels ADD COLUMN nearest_expiry TEXT;

      -- Per-receipt expiry tracking. Each received item with an expiry date
      -- gets a row here. This lets us query "what's expiring in the next N days"
      -- and trace it back to the order/receipt it came from.
      CREATE TABLE IF NOT EXISTS expiry_tracking (
        id TEXT PRIMARY KEY,
        barcode TEXT NOT NULL,
        product_name TEXT NOT NULL,
        expiry_date TEXT NOT NULL,
        qty REAL NOT NULL,
        receipt_id TEXT,
        received_at INTEGER NOT NULL,
        performed_by TEXT,
        performed_by_name TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_expiry_barcode ON expiry_tracking(barcode);
      CREATE INDEX IF NOT EXISTS idx_expiry_date ON expiry_tracking(expiry_date);

      PRAGMA user_version = 2;
    `);
    version = 2;
  }

  if (version < 3) {
    await db.execAsync(`
      -- Canonical product catalog (synced from backend).
      -- Guards pick from this list — no free-text product names.
      CREATE TABLE IF NOT EXISTS canonical_products (
        product_id TEXT PRIMARY KEY,
        canonical_name TEXT NOT NULL,
        category TEXT,
        hsn_code TEXT,
        unit TEXT NOT NULL DEFAULT 'pcs',
        pack_size REAL NOT NULL DEFAULT 1,
        has_barcode INTEGER NOT NULL DEFAULT 0,
        updated_at INTEGER NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_canonical_name ON canonical_products(canonical_name);
      CREATE INDEX IF NOT EXISTS idx_canonical_hsn ON canonical_products(hsn_code);

      -- Learned barcode → canonical product mappings.
      -- Populated when guard scans a barcode + picks from catalog.
      CREATE TABLE IF NOT EXISTS product_barcodes (
        barcode TEXT PRIMARY KEY,
        product_id TEXT NOT NULL,
        learned_from TEXT NOT NULL DEFAULT 'scan',
        learned_at INTEGER NOT NULL,
        FOREIGN KEY (product_id) REFERENCES canonical_products(product_id) ON DELETE CASCADE
      );

      -- Link order items to canonical products for name-based matching
      ALTER TABLE order_items ADD COLUMN product_id TEXT;

      CREATE INDEX IF NOT EXISTS idx_order_items_product ON order_items(product_id);

      PRAGMA user_version = 3;
    `);
    version = 3;
  }

  if (version < 4) {
    // Fresh installs already have pack_size from the initial CREATE TABLE;
    // only older DBs (created before the column was added to the base schema)
    // need the ALTER. Probe table_info to decide.
    const cols = await db.getAllAsync<{ name: string }>(
      'PRAGMA table_info(products)',
    );
    const hasPackSize = cols.some((c) => c.name === 'pack_size');
    if (!hasPackSize) {
      await db.execAsync(`ALTER TABLE products ADD COLUMN pack_size REAL;`);
    }
    await db.execAsync(`PRAGMA user_version = 4;`);
    version = 4;
  }

  if (version < 5) {
    // Mirror the canonical product's pack_size onto stock so the Stock
    // screen can render "{on_hand} × {pack_size} {unit}" without an extra
    // join at read time.
    const cols = await db.getAllAsync<{ name: string }>(
      'PRAGMA table_info(stock_levels)',
    );
    const hasPackSize = cols.some((c) => c.name === 'pack_size');
    if (!hasPackSize) {
      await db.execAsync(`ALTER TABLE stock_levels ADD COLUMN pack_size REAL;`);
    }
    await db.execAsync(`PRAGMA user_version = 5;`);
    version = 5;
  }

  if (version < 6) {
    // Track whether each canonical product already has a barcode mapped
    // server-side. The register-new-barcode suggestion list filters these
    // out so two barcodes can't map to the same product (current rule).
    const cols = await db.getAllAsync<{ name: string }>(
      'PRAGMA table_info(canonical_products)',
    );
    const hasBarcodeCol = cols.some((c) => c.name === 'has_barcode');
    if (!hasBarcodeCol) {
      await db.execAsync(`ALTER TABLE canonical_products ADD COLUMN has_barcode INTEGER NOT NULL DEFAULT 0;`);
    }
    await db.execAsync(`PRAGMA user_version = 6;`);
    version = 6;
  }
}

export function now(): number {
  return Date.now();
}

