if (pathname === "/api/inventory/stock" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  json(res, 200, { stock: await listStock(auth.siteId) });
  return true;
}

if (pathname === "/api/inventory/alerts" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  json(res, 200, { alerts: await listLowOrOut(auth.siteId) });
  return true;
}

if (pathname === "/api/inventory/products/normalize" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const rawName = asString(body.rawName) ?? asString(body.raw_name);
  if (!rawName) {
    badRequest(res, "rawName (or raw_name) is required to normalize a product name");
    return true;
  }
  try {
    const result = await normalizeProductName({
      siteId: auth.siteId,
      rawName,
    });
    json(res, 200, result);
  } catch (err) {
    logError("[Inventory] normalizeProductName failed", err, { scope: "inventory.normalize" });
    json(res, 500, {
      error: `Could not normalize "${rawName}": ${describeError(err)}`,
    });
  }
  return true;
}

if (pathname.startsWith("/api/inventory/catalog/") && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const barcode = decodeURIComponent(pathname.replace("/api/inventory/catalog/", ""));
  const product = await findProduct(auth.siteId, barcode);
  if (!product) {
    // Look ahead at open orders so the field-app can pre-fill the
    // receiving screen even for never-mapped barcodes.
    const openItem = await findOpenItemByBarcode(auth.siteId, barcode);
    json(res, 200, { product: null, openOrderItem: openItem });
    return true;
  }
  const openItem = await findOpenItemByBarcode(auth.siteId, barcode);
  json(res, 200, { product, openOrderItem: openItem });
  return true;
}

// ── Admin: Bill Upload + Extraction ─────────────────────────

// Bill extract — async. POST kicks off the LLM call in the background
// and returns a job_id under 1s (so the Bifrost ingress doesn't 504
// on the slow Gemini call). The client polls GET .../extract/:job_id
// until status is "done" or "error".
if (
  (pathname === "/api/inventory/bills/extract" ||
    pathname === "/api/inventory/bills") && // back-compat
  method === "POST"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);

  const imageSource = asString(body.image) ?? asString(body.image_url);
  if (!imageSource) {
    badRequest(
      res,
      "No bill image provided. Send the file as base64 in `image`, or a public link in `image_url`.",
    );
    return true;
  }
  const mimeType = asString(body.mime_type) ?? "image/jpeg";

  sweepExtractJobs();
  const { nanoid } = await import("nanoid");
  const jobId = `bex_${nanoid(16)}`;
  extractJobs.set(jobId, {
    status: "pending",
    siteId: auth.siteId,
    createdAt: Date.now(),
  });
  // Fire and forget — the worker writes its outcome back into the map.
  void runExtractJob(jobId, auth.siteId, imageSource, mimeType);

