// PATCH /api/inventory/canonical-products/:id — update name, category,
// hsn, unit, pack_size in place. Reused by the Orders editor so an
// admin can fix a wrong unit/pack from anywhere they see the product.
// Uses updateCanonicalProduct (direct UPDATE) so passing `null` for
// category/hsn_code actually clears the column; upsertCanonicalProduct
// COALESCEs and would silently keep the old value.
if (
  pathname.startsWith("/api/inventory/canonical-products/") &&
  !pathname.endsWith("/aliases") &&
  !pathname.endsWith("/barcodes") &&
  method === "PATCH"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  if (!auth.adminEmail) {
    adminOnly(res, "edit catalog products");
    return true;
  }
  const productId = pathname.replace("/api/inventory/canonical-products/", "");
  if (!productId) {
    badRequest(res, "Product id is required in the URL path (/api/inventory/canonical-products/:id)");
    return true;
  }
  const body = await readBodyJson(req);
  const existing = await findCanonicalProduct(productId);
  if (!existing) {
    json(res, 404, { error: `Catalog product "${productId}" not found` });
    return true;
  }
  try {
    await updateCanonicalProduct({
      productId,
      canonicalName: body.canonical_name !== undefined
        ? (asString(body.canonical_name) ?? existing.canonical_name)
        : undefined,
      category: body.category !== undefined ? asString(body.category) : undefined,
      hsnCode: body.hsn_code !== undefined ? asString(body.hsn_code) : undefined,
      unit: body.unit !== undefined ? (asString(body.unit) ?? existing.unit) : undefined,
      packSize: body.pack_size !== undefined
        ? (asNumber(body.pack_size) ?? existing.pack_size)
        : undefined,
    });
  } catch (err) {
    logError("[Inventory] updateCanonicalProduct (PATCH) failed", err, { scope: "inventory.catalog" });
    json(res, 500, {
      error: `Could not update product "${existing.canonical_name}": ${describeError(err)}`,
    });
    return true;
  }
  void syncCatalogTabToSheet(auth.siteId).catch(() => {});
  json(res, 200, { updated: true });
  return true;
}

// ── Admin: Unresolved Bill Items ───────────────────────────

if (pathname === "/api/inventory/bills/unresolved" && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  json(res, 200, {
    items: await listUnresolvedBillItems(auth.siteId),
  });
  return true;
}

if (pathname === "/api/inventory/bills/resolve" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);

  const unresolvedId = asString(body.unresolved_id);
  const productId = asString(body.product_id);
  const rememberAlias = body.remember_alias !== false;

  if (!unresolvedId || !productId) {
    const missing: string[] = [];
    if (!unresolvedId) missing.push("unresolved_id");
    if (!productId) missing.push("product_id");
    badRequest(res, `Cannot resolve bill item — missing: ${missing.join(", ")}`);
    return true;
  }

  // Resolve the unresolved item
  await resolveUnresolvedBillItem({
    id: unresolvedId,
    productId,
    resolvedBy: auth.guardName,
  });

  // Get the unresolved item details to learn the alias
  const product = await findCanonicalProduct(productId);
  if (product && rememberAlias) {
    const billItemName = asString(body.bill_item_name);
    const hsnCode = asString(body.hsn_code);
    if (billItemName) {
      await saveProductAlias({
        id: `pa_${Date.now().toString(36)}`,
        siteId: auth.siteId,
        rawName: billItemName,
        productId,
        hsnCode,
        confidence: 1.0,
        source: "admin_manual",
      });
    }
  }

  // Create the order item that was missing
  const orderId = asString(body.order_id);
  if (orderId && product) {
    const orderItemId = `oi_${Date.now().toString(36)}`;
    await createOrderItemFromBill({
      id: orderItemId,
      orderId,
      productId,
      productName: product.canonical_name,
      billItemName: asString(body.bill_item_name),
      hsnCode: asString(body.hsn_code),
      expectedQty: asNumber(body.qty) ?? 1,
      unitRate: asNumber(body.unit_rate),
      lineValue: asNumber(body.line_value),
      matchMethod: "admin_resolved",
      matchConfidence: 1.0,
    });
  }

  json(res, 200, { resolved: true });
  return true;
}

// ── Guard: Barcode → Canonical Product lookup ─────────────

if (
  pathname === "/api/inventory/canonical-products/barcode" &&
  method === "GET"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const { query } = parseUrl(req.url ?? "", true);
  const barcode = (query.barcode as string) ?? "";

