  const body = await readBodyJson(req);

  const canonicalName = asString(body.canonical_name) ?? asString(body.name);
  const unit = asString(body.unit) ?? "pcs";
  if (!canonicalName) {
    badRequest(res, "canonical_name (or name) is required to create a catalog product");
    return true;
  }

  const productId =
    asString(body.product_id) ?? `prod_${Date.now().toString(36)}`;

  try {
    await upsertCanonicalProduct({
      productId,
      siteId: auth.siteId,
      canonicalName,
      category: asString(body.category),
      hsnCode: asString(body.hsn_code),
      unit,
      packSize: asNumber(body.pack_size) ?? 1,
      createdBy: auth.guardName,
    });
  } catch (err) {
    logError("[Inventory] upsertCanonicalProduct failed", err, { scope: "inventory.catalog" });
    json(res, 500, {
      error: `Could not save product "${canonicalName}": ${describeError(err)}`,
    });
    return true;
  }

  void syncCatalogTabToSheet(auth.siteId).catch((err) =>
    logError("[Inventory] Catalog sheet sync failed", err, { scope: "inventory.sheets" }),
  );

  json(res, 200, { product_id: productId });
  return true;
}

