}

export type InventoryStockJitRow = InventoryStockRow & {
  /** ISO YYYY-MM-DD; min of future receipt expiries for this barcode.
   *  Null if none on file. Best-effort — corrections do not feed back into
   *  this today, which matches the field-app's local convention. */
  nearest_expiry: string | null;
};

/**
 * Single-row stock + pack_size + nearest-future-expiry. Used by the
 * field-app's JIT verification on EditStock / Dispense screens. The
 * stock row itself is authoritative; the expiry is a hint.
 */
export async function findStockJit(
  siteId: string,
  barcode: string,
): Promise<InventoryStockJitRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_SELECT},
        (
          SELECT to_char(MIN(r.expiry_date), 'YYYY-MM-DD')
          FROM inventory_receipts r
          WHERE r.site_id = s.site_id
            AND r.barcode = s.barcode
            AND r.expiry_date IS NOT NULL
            AND r.expiry_date >= CURRENT_DATE
        ) AS nearest_expiry
      ${STOCK_JOINS}
      WHERE s.site_id = ? AND s.barcode = ?
      LIMIT 1
    `,
    args: [siteId, barcode],
  });
  return (result.rows[0] as InventoryStockJitRow | undefined) ?? null;
}

