// JIT verification — single-row stock + nearest expiry. Called by
// EditStockScreen and DispenseScreen on open so the user is editing /
// dispensing against the freshest on_hand. 404 when the barcode has
// no stock row yet so the field-app can fall back to its local view
// (this happens for a brand-new item the device knows about locally
// but the server hasn't received a receipt for yet).
if (pathname.startsWith("/api/inventory/stock/") && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const barcode = decodeURIComponent(pathname.replace("/api/inventory/stock/", ""));
  if (!barcode) {
    badRequest(res, "barcode is required in the URL path (/api/inventory/stock/:barcode)");
    return true;
  }
  const row = await findStockJit(auth.siteId, barcode);
  if (!row) {
    json(res, 404, { error: `No stock row for barcode "${barcode}" on this site` });
    return true;
  }
  json(res, 200, { stock: row });
  return true;
}

