  pathname === "/api/inventory/canonical-products/learn-barcode" &&
  method === "POST"
) {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const barcode = asString(body.barcode);
  const productId = asString(body.product_id);
  if (!barcode || !productId) {
    const missing: string[] = [];
    if (!barcode) missing.push("barcode");
    if (!productId) missing.push("product_id");
    badRequest(res, `Cannot learn barcode mapping — missing: ${missing.join(", ")}`);
    return true;
  }

  // The field-app's outbox may carry learn_barcode rows that pre-date a
  // /reset_inventory wipe — their product_id no longer exists, so the
  // FK on product_barcodes(product_id) rejects the insert. Returning
  // 500 keeps those rows queued and they retry forever; instead, treat
  // a missing parent as "drop on the floor" so the outbox marks them
  // sent and stops banging on the server.
  try {
    await learnBarcode({
      siteId: auth.siteId,
      barcode,
      productId,
      learnedFrom: "scan",
    });
  } catch (err) {
    if (isForeignKeyViolation(err)) {
      json(res, 200, { learned: false, reason: "product_missing" });
      return true;
    }
    throw err;
  }
  // Push the new barcode into the Sheet's Catalog tab (debounced).
  void syncCatalogTabToSheet(auth.siteId).catch(() => {});

  json(res, 200, { learned: true });
  return true;
}

