// JIT verification — single-row catalog read with live-computed
// `has_barcode` and `primary_barcode`. Called by the field-app's
// catalog picker right before navigating to ReceivingScreen, so the
// user is committing against the freshest server state (catches
// barcode mappings learned by another guard / admin / bill flow that
// hadn't been pulled by the periodic sync yet).
//
// Slug must be a bare product_id (no further slashes) and not one of
// the exact-match siblings (`/barcode`, `/learn-barcode`) which are
// handled above with their own routes.
if (
  pathname.startsWith("/api/inventory/canonical-products/") &&
  method === "GET"
) {
  const slug = pathname.replace("/api/inventory/canonical-products/", "");
  if (
    slug.length > 0 &&
    !slug.includes("/") &&
    slug !== "barcode" &&
    slug !== "learn-barcode"
  ) {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const product = await findCanonicalProductFull(auth.siteId, slug);
    if (!product) {
      json(res, 404, { error: `Catalog product "${slug}" not found on this site` });
      return true;
    }
    json(res, 200, { product });
    return true;
  }
  // Slug shape didn't match — fall through so the `/aliases` and
  // `/barcodes` sub-routes below can match.
}

