import { useEffect, useState } from 'react';

export type CacheKey = 'catalog' | 'stock' | 'orders' | 'alerts';

export type CacheState = 'cold' | 'warm' | 'refreshing' | 'error' | 'offline';

const states = new Map<CacheKey, CacheState>();
type Listener = (state: CacheState) => void;
const listeners = new Map<CacheKey, Set<Listener>>();

export function getCacheState(key: CacheKey): CacheState {
  return states.get(key) ?? 'cold';
}

export function setCacheState(key: CacheKey, state: CacheState): void {
  if (states.get(key) === state) return;
  states.set(key, state);
  const ls = listeners.get(key);
  if (!ls) return;
  for (const l of ls) {
    try { l(state); } catch { /* listener errors must not break the notifier */ }
  }
}

export function onCacheStateChange(key: CacheKey, l: Listener): () => void {
  let set = listeners.get(key);
  if (!set) {
    set = new Set();
    listeners.set(key, set);
  }
  set.add(l);
  return () => { set!.delete(l); };
}

/** React hook — re-renders the calling component when this key's state
 *  transitions. Initial value is the current state (no flash). */
export function useCacheStatus(key: CacheKey): CacheState {
  const [s, setS] = useState<CacheState>(() => getCacheState(key));
  useEffect(() => onCacheStateChange(key, setS), [key]);
  return s;
}

/** Helpers callers use to drive the state machine. Centralised so the
 *  transitions stay consistent across warmCache, per-screen refetches,
 *  and post-write invalidation. */
export const cache = {
  refreshing: (key: CacheKey) => setCacheState(key, 'refreshing'),
  warm: (key: CacheKey) => setCacheState(key, 'warm'),
  error: (key: CacheKey) => setCacheState(key, 'error'),
  offline: (key: CacheKey) => setCacheState(key, 'offline'),
};

/** Reset every cache to cold. Called on logout so the next session
 *  starts clean (no stale "warm" hint from a different guard's data). */
export function resetAllCacheStates(): void {
  const keys: CacheKey[] = ['catalog', 'stock', 'orders', 'alerts'];
  for (const k of keys) setCacheState(k, 'cold');
}

