</Card>

<View style={styles.qtySection}>
  <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
    {t('howMany').toUpperCase()}
  </Text>
  {/* Max is the JIT-verified count when we have it; otherwise
