function CatalogTab() {
  const queryClient = useQueryClient();
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
  const products = productsQuery.data?.data?.products ?? [];
  const [showForm, setShowForm] = useState(false);
  const [draft, setDraft] = useState({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
  const [filter, setFilter] = useState("");

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return products;
    return products.filter((p) =>
      p.canonical_name.toLowerCase().includes(q) ||
      (p.category ?? "").toLowerCase().includes(q) ||
      (p.hsn_code ?? "").toLowerCase().includes(q),
    );
  }, [products, filter]);

  const createMutation = useMutation({
    mutationFn: () => createCanonicalProduct({
      canonical_name: draft.canonical_name,
      category: draft.category || undefined,
      hsn_code: draft.hsn_code || undefined,
      unit: draft.unit,
      pack_size: draft.pack_size,
    }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Create failed")); return; }
      toastSuccess("Product created");
      setShowForm(false);
      setDraft({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
      void queryClient.invalidateQueries({ queryKey: ["inv-canonical"] });
    },
    onError: (err) => toastError(err, "Create failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
        <input
          type="text"
          placeholder="Filter by name, category, HSN…"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ ...input, flex: 1, maxWidth: 360 }}
        />
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" onClick={() => void productsQuery.refetch()} style={ghostBtn}>
            <RefreshCw size={14} /> Refresh
          </button>
          <button
            type="button"
            style={ghostBtn}
            onClick={() => {
              if (confirm(
                "Drop every learned bill-name → product mapping for this site?\n\n" +
                "Standard products and barcode mappings stay. This only clears\n" +
                "the alias cache that auto-fills bill upload suggestions. Use\n" +
                "this if upload suggestions have been pointing to the wrong\n" +
                "products.",
              )) {
                void clearAliases().then((res) => {
                  if (res.ok) toastSuccess(`Cleared ${res.data.deleted} alias(es)`);
                  else toastError(errorMessage((res.data as { error?: string }).error, "Clear failed"));
                });
              }
            }}
          >
            Clear learned aliases
          </button>
          <button type="button" className="primary-button" onClick={() => setShowForm(true)}>
            <Plus size={14} /> New product
          </button>
        </div>
      </div>

      {showForm && (
        <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 14, marginBottom: 12 }}>
          <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr" }}>
            <FieldLabel label="Standard name">
              <input type="text" value={draft.canonical_name} onChange={(e) => setDraft({ ...draft, canonical_name: e.target.value })} style={input} />
            </FieldLabel>
            <FieldLabel label="Category">
              <CategoryCombobox value={draft.category} catalog={products} onChange={(v) => setDraft({ ...draft, category: v })} />
            </FieldLabel>
            <FieldLabel label="HSN">
              <input type="text" value={draft.hsn_code} onChange={(e) => setDraft({ ...draft, hsn_code: e.target.value })} style={input} />
            </FieldLabel>
            <FieldLabel label="Unit">
              <select value={draft.unit} onChange={(e) => setDraft({ ...draft, unit: e.target.value })} style={input}>
                <option value="pcs">pcs</option><option value="kg">kg</option><option value="g">g</option>
                <option value="l">l</option><option value="ml">ml</option><option value="pack">pack</option>
              </select>
            </FieldLabel>
            <FieldLabel label="Pack size">
              <NumericInput value={draft.pack_size} onChange={(v) => setDraft({ ...draft, pack_size: v })} style={input} />
            </FieldLabel>
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 10, justifyContent: "flex-end" }}>
            <button type="button" onClick={() => setShowForm(false)} style={ghostBtn}>Cancel</button>
            <button type="button" className="primary-button" disabled={!draft.canonical_name.trim() || createMutation.isPending} onClick={() => createMutation.mutate()}>
              {createMutation.isPending ? "Creating…" : "Create"}
            </button>
          </div>
        </div>
      )}

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={{ ...th, width: 28 }}></th>
              <th style={th}>Standard name</th>
              <th style={th}>Category</th>
              <th style={th}>HSN</th>
              <th style={th}>Unit</th>
              <th style={th}>Pack</th>
              <th style={th}>Created</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((p) => (
              <CatalogProductRow key={p.product_id} product={p} />
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={7} style={{ ...td, textAlign: "center", color: "var(--muted)", padding: 24 }}>
                {productsQuery.isLoading ? "Loading…" : "No products. Seed the catalog or create one to begin."}
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

