function CategoryCombobox({
  value,
  catalog,
  onChange,
  style,
}: {
  value: string;
  catalog: CanonicalProduct[];
  onChange: (v: string) => void;
  style?: React.CSSProperties;
}) {
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!wrapRef.current) return;
      if (!wrapRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const options = useMemo(() => {
    const used = new Set<string>();
    for (const p of catalog) {
      const c = (p.category ?? "").trim();
      if (c) used.add(c);
    }
    // Union: seed list + any custom categories already in the catalog.
    const merged = [...new Set([...CATEGORY_SEED, ...Array.from(used)])];
    const q = value.trim().toLowerCase();
    if (!q) return merged.sort((a, b) => a.localeCompare(b));
    return merged
      .filter((c) => c.toLowerCase().includes(q))
      .sort((a, b) => {
        const al = a.toLowerCase();
        const bl = b.toLowerCase();
        const aStarts = al.startsWith(q) ? 0 : 1;
        const bStarts = bl.startsWith(q) ? 0 : 1;
        if (aStarts !== bStarts) return aStarts - bStarts;
        return a.localeCompare(b);
      });
  }, [catalog, value]);

  function commit(c: string) {
    onChange(c);
    setOpen(false);
    setActiveIdx(0);
  }

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <input
        type="text"
        value={value}
        onChange={(e) => { onChange(e.target.value); setOpen(true); setActiveIdx(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActiveIdx((i) => Math.min(options.length - 1, i + 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActiveIdx((i) => Math.max(0, i - 1)); }
          else if (e.key === "Enter" && open && options[activeIdx]) { e.preventDefault(); commit(options[activeIdx]); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        placeholder="Type or pick a category…"
        autoComplete="off"
        style={style ?? input}
      />
      {open && options.length > 0 && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 2px)",
            left: 0,
            right: 0,
            zIndex: 30,
            maxHeight: 200,
            overflowY: "auto",
            background: "var(--surface, #fff)",
            border: "1px solid var(--line)",
            borderRadius: 6,
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
          }}
        >
          {options.map((c, i) => (
            <div
              key={c}
              onMouseDown={(e) => { e.preventDefault(); commit(c); }}
              onMouseEnter={() => setActiveIdx(i)}

