/**
 * Suggestive product picker for the order-item add row. Replaces the
 * old <select> that listed every catalog product in a single dropdown
 * (unscrollable past ~50 items on most setups). The admin types a few
 * letters of the name or HSN; matches drop down in real time and the
 * arrow keys move the highlight. Selecting one fires `onSelect` with
 * the full canonical product so the parent can auto-fill HSN, pack,
 * unit, and reset qty to 1.
 *
 * Visually it's a plain text input — no chevron or fake select chrome —
 * because once a product is picked we want the input to show the chosen
 * name. Re-typing clears the selection.
 */
function ProductTypeahead({
  products,
  selected,
  onSelect,
  onClear,
  placeholder,
}: {
  products: CanonicalProduct[];
  selected: CanonicalProduct | null;
  onSelect: (p: CanonicalProduct) => void;
  onClear: () => void;
  placeholder?: string;
}) {
  const [query, setQuery] = useState(selected?.canonical_name ?? "");
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  // Re-sync the visible text when the parent clears or swaps the
  // selection externally (e.g. after a successful add).
  useEffect(() => {
    setQuery(selected?.canonical_name ?? "");
  }, [selected]);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!wrapRef.current) return;
      if (!wrapRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const options = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) {
      return [...products]
        .sort((a, b) => a.canonical_name.localeCompare(b.canonical_name))
        .slice(0, 20);
    }
    const scored: Array<{ p: CanonicalProduct; score: number }> = [];
    for (const p of products) {
      const name = p.canonical_name.toLowerCase();
      const hsn = (p.hsn_code ?? "").toLowerCase();
      const cat = (p.category ?? "").toLowerCase();
      let score = 0;
      if (name === q) score = 4;
      else if (name.startsWith(q)) score = 3;
      else if (name.includes(q)) score = 2;
      else if (hsn.includes(q) || cat.includes(q)) score = 1;
      if (score > 0) scored.push({ p, score });
    }
    scored.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      return a.p.canonical_name.localeCompare(b.p.canonical_name);
    });
    return scored.slice(0, 20).map((x) => x.p);
  }, [products, query]);

  function commit(p: CanonicalProduct) {
    onSelect(p);
    setQuery(p.canonical_name);
    setOpen(false);
    setActiveIdx(0);
  }

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <input
        type="text"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setOpen(true);
          setActiveIdx(0);
          // Typing after a selection means the admin is searching again —
          // clear the locked-in product so HSN/pack/unit stop showing
          // stale values.
          if (selected) onClear();
        }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActiveIdx((i) => Math.min(options.length - 1, i + 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActiveIdx((i) => Math.max(0, i - 1)); }
          else if (e.key === "Enter" && open && options[activeIdx]) { e.preventDefault(); commit(options[activeIdx]); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        placeholder={placeholder ?? "Type product name, HSN, or category…"}
        autoComplete="off"
        style={cellInput}
      />
      {open && options.length > 0 && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 2px)",
            left: 0,
            // Wider than the input so long product names + their pack/unit
            // hint don't get truncated.
            minWidth: 280,
            zIndex: 30,
            maxHeight: 260,
            overflowY: "auto",
            background: "var(--surface, #fff)",
            border: "1px solid var(--line)",
            borderRadius: 6,
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
          }}
        >
          {options.map((p, i) => (
            <div
              key={p.product_id}
              onMouseDown={(e) => { e.preventDefault(); commit(p); }}
              onMouseEnter={() => setActiveIdx(i)}
              style={{
                padding: "6px 10px",
                cursor: "pointer",
                background: i === activeIdx ? "var(--line)" : "transparent",
                fontSize: 12,
                display: "grid",
                gridTemplateColumns: "1fr auto",
                gap: 8,
                alignItems: "center",
              }}
            >
              <div style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                <span>{p.canonical_name}</span>
                {p.hsn_code ? (
                  <span style={{ color: "var(--muted)", marginLeft: 6 }}>HSN {p.hsn_code}</span>
                ) : null}
              </div>
              <span style={{ color: "var(--muted)", fontSize: 11 }}>
                {p.pack_size} {p.unit}
              </span>
            </div>
          ))}
        </div>
      )}
      {open && options.length === 0 && query.trim().length > 0 && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 2px)",
            left: 0,
            minWidth: 280,
            zIndex: 30,
            background: "var(--surface, #fff)",
            border: "1px solid var(--line)",
            borderRadius: 6,
            padding: "6px 10px",
            fontSize: 12,
            color: "var(--muted)",
            fontStyle: "italic",
          }}
        >
          No matching products.
        </div>
      )}
    </div>
  );
}

function AddItemRow({ orderId, onAdded }: { orderId: string; onAdded: () => void }) {
  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
  const products = productsQuery.data?.data?.products ?? [];
  // Hold the full product object so HSN / pack / unit are available for
  // auto-fill without a second lookup at submit time.
  const [selected, setSelected] = useState<CanonicalProduct | null>(null);
  const [qty, setQty] = useState<number>(1);
  const [rate, setRate] = useState<number | null>(null);

  const addMutation = useMutation({
    mutationFn: () => {
      if (!selected) throw new Error("Pick a product");
      return addOrderItem(orderId, {
        product_id: selected.product_id,
        canonical_name: selected.canonical_name,
        hsn_code: selected.hsn_code,
        qty,
        rate,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Add failed")); return; }
      toastSuccess("Item added");
      setSelected(null);
      setQty(1);
      setRate(null);
      onAdded();
    },
    onError: (err) => toastError(err, "Add failed"),
  });

  return (
    <tr style={{ background: "var(--surface, #fafafa)" }}>
      <td style={tdCell}>
        <ProductTypeahead
          products={products}
          selected={selected}
          onSelect={(p) => {
            setSelected(p);
            // Sensible defaults for the order line: qty 1, rate blank
            // (rate varies per bill — admin types it after selecting).
            setQty(1);
            setRate(null);
          }}
          onClear={() => setSelected(null)}
        />
      </td>
      <td style={tdCell}>
        {/* HSN auto-fills from the catalog. Display-only so admins can't
            accidentally diverge the order from the standard product's
            HSN — edit at the catalog level instead. */}
        <span style={{ fontSize: 12, color: selected?.hsn_code ? "var(--text)" : "var(--muted)" }}>
          {selected?.hsn_code ?? "—"}
        </span>
      </td>
      <td style={tdCell}>
        <NumericInput value={qty} onChange={setQty} style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={tdCell}>
        <NumericInput value={rate ?? 0} onChange={(v) => setRate(v)} placeholder="rate" style={{ ...cellInput, textAlign: "right" }} />
      </td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        {/* Pack size from the selected catalog product. Same reasoning
            as HSN — edit at catalog level, not per-order. */}
        <span style={{ fontSize: 12, color: selected ? "var(--text)" : "var(--muted)" }}>
          {selected ? selected.pack_size : "—"}
        </span>
      </td>
      <td style={tdCell}>
        <span style={{ fontSize: 12, color: selected ? "var(--text)" : "var(--muted)" }}>
          {selected?.unit ?? "—"}
        </span>
      </td>
      <td style={{ ...tdCell, textAlign: "right", color: "var(--muted)" }}>
        {/* Received is "—" until the item exists in the order — there's
            nothing to have received yet. The colSpan-3 merge that used
            to span Pack/Unit/Received here was misleading because
            Pack/Unit ARE known the moment a product is picked. */}
        —
      </td>
      <td style={{ ...tdCell, textAlign: "right" }}>
        <button
          type="button"
          className="primary-button"
          disabled={!selected || addMutation.isPending}
          onClick={() => addMutation.mutate()}
          style={{ padding: "4px 10px", fontSize: 12, display: "inline-flex", alignItems: "center", gap: 4 }}
          title="Add this item to the order"
        >
          {addMutation.isPending ? "Adding…" : (<><Plus size={14} /> Add</>)}
        </button>
      </td>
    </tr>
  );
}

