input.new_string:
function ProductTypeahead({
  products,
  selected,
  onSelect,
  onClear,
  placeholder,
}: {
  products: CanonicalProduct[];
  selected: CanonicalProduct | null;
  onSelect: (p: CanonicalProduct) => void;
  onClear: () => void;
  placeholder?: string;
}) {
  const [query, setQuery] = useState(selected?.canonical_name ?? "");
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  // Portal-anchored position of the dropdown. Recomputed every time
  // `open` flips, on window scroll, and on resize so the panel stays
  // glued to the input even if the page scrolls (the parent table is
  // sometimes inside a scrollable container).
  const [anchor, setAnchor] = useState<{ left: number; top: number; width: number } | null>(null);

  // Re-sync the visible text when the parent clears or swaps the
  // selection externally (e.g. after a successful add).
  useEffect(() => {
    setQuery(selected?.canonical_name ?? "");
  }, [selected]);

  useEffect(() => {
    // Close on outside click — but anchor handling must treat clicks
    // INSIDE the portal'd dropdown as inside too, so we identify the
    // panel via a marker attribute.
    function onDocClick(e: MouseEvent) {
      const target = e.target as Node | null;
      if (!target) return;
      if (wrapRef.current?.contains(target)) return;
      const panel = (target as HTMLElement).closest?.("[data-product-typeahead-panel]");
      if (panel) return;
      setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  // Track the input's position so the portal'd panel renders right
  // under it. Updates on open + on scroll/resize while open.
  useEffect(() => {
    if (!open) return;
    function update() {
      const r = inputRef.current?.getBoundingClientRect();
      if (!r) return;
      setAnchor({ left: r.left, top: r.bottom + 2, width: r.width });
    }
    update();
    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [open]);

