    canonical_name: p.canonical_name,
    category: p.category ?? "",
    hsn_code: p.hsn_code ?? "",
    unit: p.unit,
    pack_size: p.pack_size,
  });
  setEditing(true);
  // Open the expansion alongside so admins manage barcodes + vendor
  // aliases in the same flow as the inline-row edit. Saves the "edit
  // → save → click chevron → edit barcode → click chevron" dance.
  setOpen(true);
}

// Cancel = leave edit mode AND collapse the expansion that startEdit
// forced open. If the admin had the expansion open before they
// clicked Edit, that state is lost on cancel — acceptable because
// there's no clean way to distinguish "open because Edit forced it"
// from "open because admin clicked the chevron".
function cancelEdit() {
  setEditing(false);
  setOpen(false);
}

