/**
 * Bill Matcher — maps vendor bill line items to canonical products.
 *
 * Multi-step matching pipeline:
 *   1. Exact name match against canonical_products
 *   2. Product alias cache hit (raw_name + optional HSN context)
 *   3. HSN-scoped fuzzy match (Fuse.js within same HSN category)
 *   4. LLM normalization (existing normalizer.ts)
 *   5. Unresolved → admin queue
 *
 * Each successful match learns an alias for future free lookups.
 * Over time, the alias cache grows and the LLM is called less.
 */

import { nanoid } from "nanoid";
import type { BillLineItem, ExtractedBill } from "./bill-extractor";
import {
  createOrderFromBill,
  createOrderItemFromBill,
  findCanonicalProductByName,
  findProductAlias,
  insertUnresolvedBillItem,
  listCanonicalProductsByHsn,
  saveProductAlias,
  upsertCanonicalProduct,
  type CanonicalProduct,
} from "./db";
import { normalizeProductName } from "./normalizer";

export type MatchResult = {
  matched: boolean;
  productId: string | null;
  canonicalName: string;
  confidence: number;
  method: "exact" | "alias" | "hsn_fuzzy" | "normalized" | "unresolved";
};

/**
 * Simple fuzzy name comparison. Returns a similarity score 0-1.
 * Avoids pulling in Fuse.js server-side for a simple use case.
 */
function fuzzyScore(a: string, b: string): number {
  const la = a.toLowerCase().replace(/[^a-z0-9]/g, "");
  const lb = b.toLowerCase().replace(/[^a-z0-9]/g, "");
  if (la === lb) return 1.0;
  if (la.includes(lb) || lb.includes(la)) return 0.8;

  // Bigram similarity (Dice coefficient)
  const bigramsA = new Set<string>();
  for (let i = 0; i < la.length - 1; i++) bigramsA.add(la.slice(i, i + 2));
  const bigramsB = new Set<string>();
  for (let i = 0; i < lb.length - 1; i++) bigramsB.add(lb.slice(i, i + 2));

  if (bigramsA.size === 0 || bigramsB.size === 0) return 0;

  let intersection = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersection++;
  }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

export type Suggestion = {
  productId: string;
  canonicalName: string;
  unit: string;
  packSize: number;
  hsnCode: string | null;
  category: string | null;
  score: number;
  method: "exact" | "alias" | "hsn_fuzzy" | "normalized" | "global_fuzzy";
};

/**
 * Non-mutating: returns the top-N catalog suggestions for a bill line.
 * Does NOT write aliases or learn anything — used by the admin review
 * UI so the user makes the final call.
 */
export async function suggestForBillLine(
  siteId: string,
  item: BillLineItem,
  topN = 3,
): Promise<Suggestion[]> {
  const name = item.item_purchased.trim();
  const hsn = item.hsn_code?.trim() || null;
  const pool = new Map<string, Suggestion>();
  const add = (s: Suggestion) => {
    const cur = pool.get(s.productId);
    if (!cur || s.score > cur.score) pool.set(s.productId, s);
  };

  // Exact name → top suggestion
  const exact = await findCanonicalProductByName(siteId, name);
  if (exact) {
    add({
      productId: exact.product_id,
      canonicalName: exact.canonical_name,
      unit: exact.unit,
      packSize: exact.pack_size,
      hsnCode: exact.hsn_code,
      category: exact.category,
      score: 1.0,
      method: "exact",
    });
  }

  // Alias cache (HSN-aware) — peek without learning
  const alias = await findProductAlias(siteId, name, hsn);
  if (alias) {
    const p = await import("./db").then((m) =>
      m.findCanonicalProduct(alias.product_id),
    );
    if (p) {
      add({
        productId: p.product_id,
        canonicalName: p.canonical_name,
        unit: p.unit,
        packSize: p.pack_size,
        hsnCode: p.hsn_code,
        category: p.category,
        score: alias.confidence,
        method: "alias",
      });
    }
  }

  // HSN-scoped fuzzy: top candidates in same HSN bucket
  if (hsn) {
    const candidates = await listCanonicalProductsByHsn(siteId, hsn);
    for (const c of candidates) {
      const score = fuzzyScore(name, c.canonical_name);
      if (score >= 0.4) {
        add({
          productId: c.product_id,
          canonicalName: c.canonical_name,
          unit: c.unit,
          packSize: c.pack_size,
          hsnCode: c.hsn_code,
          category: c.category,
          score,
          method: "hsn_fuzzy",
        });
      }
    }
  }

  // LLM normalization — if it maps to an existing canonical, surface it
  try {
    const normalized = await normalizeProductName({ siteId, rawName: name });
    if (normalized.confidence >= 0.6) {
      const product = await findCanonicalProductByName(siteId, normalized.canonical);
      if (product) {
        add({
          productId: product.product_id,
          canonicalName: product.canonical_name,
          unit: product.unit,
          packSize: product.pack_size,
          hsnCode: product.hsn_code,
          category: product.category,
          score: normalized.confidence,
          method: "normalized",
        });
      }
    }
  } catch {
    // ignore LLM errors — fall through
  }

  // Last-resort: global fuzzy across the whole catalog (no HSN). Cheap on
  // small catalogs; if it ever bites, switch to a fuse-style index.
  if (pool.size === 0) {
    const all = await import("./db").then((m) => m.listCanonicalProducts(siteId));
    for (const c of all) {
      const score = fuzzyScore(name, c.canonical_name);
      if (score >= 0.4) {
        add({
          productId: c.product_id,
          canonicalName: c.canonical_name,
          unit: c.unit,
          packSize: c.pack_size,
          hsnCode: c.hsn_code,
          category: c.category,
          score,
          method: "global_fuzzy",
        });
      }
    }
  }

  return Array.from(pool.values())
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);
}

/**
 * Match a single bill line item to a canonical product.
 */
export async function matchBillLineToProduct(
  siteId: string,
  item: BillLineItem,
): Promise<MatchResult> {
  const name = item.item_purchased.trim();
  const hsn = item.hsn_code?.trim() || null;

  // Step 1: Exact name match in canonical_products
  const exact = await findCanonicalProductByName(siteId, name);
  if (exact) {
    return {
      matched: true,
      productId: exact.product_id,
      canonicalName: exact.canonical_name,
      confidence: 1.0,
      method: "exact",
    };
  }

  // Step 2: Product alias cache hit (HSN-aware)
  const alias = await findProductAlias(siteId, name, hsn);
  if (alias && alias.confidence >= 0.7) {
    return {
      matched: true,
      productId: alias.product_id,
      canonicalName: alias.raw_name,
      confidence: alias.confidence,
      method: "alias",
    };
  }

  // Step 3: HSN-scoped fuzzy match
  if (hsn) {
    const candidates = await listCanonicalProductsByHsn(siteId, hsn);
    if (candidates.length > 0) {
      let bestMatch: CanonicalProduct | null = null;
      let bestScore = 0;

      for (const candidate of candidates) {
        const score = fuzzyScore(name, candidate.canonical_name);
        if (score > bestScore) {
          bestScore = score;
          bestMatch = candidate;
        }
      }

      if (bestMatch && bestScore >= 0.6) {
        // Learn this alias for next time
        await saveProductAlias({
          id: `pa_${nanoid(12)}`,
          siteId,
          rawName: name,
          productId: bestMatch.product_id,
          hsnCode: hsn,
          confidence: bestScore,
          source: "hsn_fuzzy",
        });

        return {
          matched: true,
          productId: bestMatch.product_id,
          canonicalName: bestMatch.canonical_name,
          confidence: bestScore,
          method: "hsn_fuzzy",
        };
      }
    }
  }

  // Step 4: LLM normalization
  try {
    const normalized = await normalizeProductName({ siteId, rawName: name });
    if (normalized.confidence >= 0.7) {
      const product = await findCanonicalProductByName(
        siteId,
        normalized.canonical,
      );
      if (product) {
        // Learn alias
        await saveProductAlias({
          id: `pa_${nanoid(12)}`,
          siteId,
          rawName: name,
          productId: product.product_id,
          hsnCode: hsn,
          confidence: normalized.confidence,
          source: "llm_normalized",
        });

        return {
          matched: true,
          productId: product.product_id,
          canonicalName: product.canonical_name,
          confidence: normalized.confidence,
          method: "normalized",
        };
      }
    }
  } catch {
    // LLM failed — fall through to unresolved
  }

  // Step 5: Unresolved
  return {
    matched: false,
    productId: null,
    canonicalName: name,
    confidence: 0,
    method: "unresolved",
  };
}

export type ValidatedBillItem = {
  /** "use_existing" maps the bill line to a known canonical_product.
   *  "create_new" registers a new canonical_product. */
  action: "use_existing" | "create_new";
  product_id?: string | null; // required when action = "use_existing"
  canonical_name: string;
  category?: string | null;
  hsn_code?: string | null;
  unit: string;
  pack_size: number;
  qty: number;
  rate?: number | null;
  value?: number | null;
  bill_item_name: string; // verbatim from the bill — saved as alias
};

export type ValidatedBill = {
  vendor_name?: string | null;
  bill_number?: string | null;
  bill_date?: string | null;
  bill_photo_url?: string | null;
  grand_total?: number | null;
  items: ValidatedBillItem[];
};

/**
 * Commit an admin-validated bill: create new canonical products as
 * needed, write the order + order_items, save aliases. Returns the
 * created orderId + per-item commit info so the caller can append
 * to the "Ordered" Google Sheet tab.
 */
export async function processValidatedBill(
  siteId: string,
  createdBy: string,
  bill: ValidatedBill,
): Promise<{
  orderId: string;
  committed: Array<{
    productId: string;
    canonicalName: string;
    unit: string;
    packSize: number;
    billItemName: string;
    hsnCode: string | null;
    qty: number;
    rate: number | null;
    value: number | null;
  }>;
}> {
  const orderId = `ord_${nanoid(12)}`;
  await createOrderFromBill({
    id: orderId,
    siteId,
    vendor: bill.vendor_name ?? null,
    billNumber: bill.bill_number ?? null,
    billDate: bill.bill_date ?? null,
    billPhotoUrl: bill.bill_photo_url ?? null,
    grandTotal: bill.grand_total ?? null,
    expectedAt: bill.bill_date ?? new Date().toISOString(),
  });

  const committed: Array<{
    productId: string;
    canonicalName: string;
    unit: string;
    packSize: number;
    billItemName: string;
    hsnCode: string | null;
    qty: number;
    rate: number | null;
    value: number | null;
  }> = [];

  for (const item of bill.items) {
    let productId = item.product_id ?? null;
    let canonicalName = item.canonical_name;
    let unit = item.unit;
    let packSize = item.pack_size;

    if (item.action === "create_new" || !productId) {
      // Admin may have typed a name that already exists in the catalog
      // (the matcher missed it, or they didn't realize). Reuse rather
      // than insert — the (site_id, canonical_name) unique constraint
      // would reject a duplicate insert anyway.
      const existing = await findCanonicalProductByName(siteId, canonicalName);
      if (existing) {
        productId = existing.product_id;
        unit = existing.unit;
        packSize = existing.pack_size;
        canonicalName = existing.canonical_name;
      } else {
        productId = `prod_${nanoid(10)}`;
        await upsertCanonicalProduct({
          productId,
          siteId,
          canonicalName,
          category: item.category ?? null,
          hsnCode: item.hsn_code ?? null,
          unit,
          packSize,
          createdBy,
        });
      }
    } else {
      // use_existing — keep server canonical_name / unit / pack_size canonical
      // but record what the admin saw. If admin edited canonical_name, the
      // existing canonical product takes precedence (don't silently rename
      // catalog rows under the admin).
      const existing = await findCanonicalProductByName(siteId, canonicalName);
      if (existing) {
        productId = existing.product_id;
        unit = existing.unit;
        packSize = existing.pack_size;
        canonicalName = existing.canonical_name;
      }
    }

    // Save the alias so this vendor's variant of the name auto-resolves next time
    if (item.bill_item_name && item.bill_item_name.trim() !== canonicalName) {
      try {
        await saveProductAlias({
          id: `pa_${nanoid(12)}`,
          siteId,
          rawName: item.bill_item_name,
          productId,
          hsnCode: item.hsn_code ?? null,
          confidence: 1.0,
          source: "admin_validated",
        });
      } catch {
        // unique-violation on rawname+hsn is fine — already learned
      }
    }

    const orderItemId = `oi_${nanoid(12)}`;
    await createOrderItemFromBill({
      id: orderItemId,
      orderId,
      productId,
      productName: canonicalName,
      billItemName: item.bill_item_name,
      hsnCode: item.hsn_code ?? null,
      expectedQty: item.qty,
      unitRate: item.rate ?? null,
      lineValue: item.value ?? null,
      matchMethod: item.action === "create_new" ? "admin_new" : "admin_validated",
      matchConfidence: 1.0,
    });

    committed.push({
      productId,
      canonicalName,
      unit,
      packSize,
      billItemName: item.bill_item_name,
      hsnCode: item.hsn_code ?? null,
      qty: item.qty,
      rate: item.rate ?? null,
      value: item.value ?? null,
    });
  }

  return { orderId, committed };
}

/**
 * Process an entire extracted bill: match each line item, create
 * an order, and queue unresolved items for admin resolution.
 *
 * Returns the created order ID and per-line-item match results.
 */
export async function processBill(
  siteId: string,
  bill: ExtractedBill,
  billPhotoUrl?: string | null,
): Promise<{
  orderId: string;
  results: Array<{
    lineItem: BillLineItem;
    match: MatchResult;
    orderItemId: string | null;
  }>;
  summary: {
    total: number;
    matched: number;
    unresolved: number;
  };
}> {
  const orderId = `ord_${nanoid(12)}`;

  // Create the order
  await createOrderFromBill({
    id: orderId,
    siteId,
    vendor: bill.vendor_name,
    billNumber: bill.bill_number,
    billDate: bill.bill_date,
    billPhotoUrl: billPhotoUrl ?? null,
    grandTotal: bill.grand_total,
    expectedAt: bill.bill_date ?? new Date().toISOString(),
  });

  const results: Array<{
    lineItem: BillLineItem;
    match: MatchResult;
    orderItemId: string | null;
  }> = [];

  let matchedCount = 0;
  let unresolvedCount = 0;

  for (const lineItem of bill.line_items) {
    const match = await matchBillLineToProduct(siteId, lineItem);

    if (match.matched && match.productId) {
      // Create order item linked to canonical product
      const orderItemId = `oi_${nanoid(12)}`;
      await createOrderItemFromBill({
        id: orderItemId,
        orderId,
        productId: match.productId,
        productName: match.canonicalName,
        billItemName: lineItem.item_purchased,
        hsnCode: lineItem.hsn_code,
        expectedQty: lineItem.qty,
        unitRate: lineItem.rate,
        lineValue: lineItem.value,
        matchMethod: match.method,
        matchConfidence: match.confidence,
      });

      results.push({ lineItem, match, orderItemId });
      matchedCount++;
    } else {
      // Queue for admin resolution
      const unresolvedId = `ubli_${nanoid(12)}`;
      await insertUnresolvedBillItem({
        id: unresolvedId,
        siteId,
        orderId,
        billItemName: lineItem.item_purchased,
        hsnCode: lineItem.hsn_code,
        qty: lineItem.qty,
        unitRate: lineItem.rate,
        lineValue: lineItem.value,
      });

      results.push({ lineItem, match, orderItemId: null });
      unresolvedCount++;
    }
  }

  return {
    orderId,
    results,
    summary: {
      total: bill.line_items.length,
      matched: matchedCount,
      unresolved: unresolvedCount,
    },
  };
}

