function itemToRow(it: BillExtractItem): ReviewRow {
  const rawUnit = (it.unit_type ?? "").toLowerCase();

  // Exact-name match in the catalog (case-insensitive). The backend's
  // suggester returns this with method="exact" + score=1. When we see
  // it, auto-apply — the alias cache poisoning that bit us before is
  // only a risk for fuzzy / alias / normalized matches, NOT exact-name
  // hits, which are deterministic.
  const exact = it.suggestions.find(
    (s) =>
      s.method === "exact" ||
      s.canonicalName.trim().toLowerCase() === it.bill_item_name.trim().toLowerCase(),
  );

  if (exact) {
    return {
      tempId: it.tempId,
      bill_item_name: it.bill_item_name,
      canonical_name: exact.canonicalName,
      category: exact.category ?? it.category ?? "",
      hsn_code: exact.hsnCode ?? it.hsn_code ?? "",
      qty: it.qty,
      rate: it.rate,
      value: it.value,
      unit: exact.unit,
      pack_size: exact.packSize,
      action: "use_existing",
      product_id: exact.productId,
      suggestions: it.suggestions,
    };
  }

  // No exact hit — pre-fill from the LLM's extraction and let the admin
  // pick a suggestion (or type into the combobox) if they want to map.
  return {
    tempId: it.tempId,
    bill_item_name: it.bill_item_name,
    canonical_name: it.bill_item_name,
    category: it.category ?? "",
    hsn_code: it.hsn_code ?? "",
    qty: it.qty,
    rate: it.rate,
    value: it.value,
    unit: UNIT_OPTIONS.includes(rawUnit) ? rawUnit : (rawUnit || "pcs"),
    pack_size: it.unit_value && it.unit_value > 0 ? it.unit_value : 1,
    action: "create_new",
    product_id: null,
    suggestions: it.suggestions,
  };
}

function BillField({
  label, value, onChange, type = "text",
}: { label: string; value: string | null; onChange: (v: string | null) => void; type?: string }) {
  const missing = !value;
  return (
    <label style={{ display: "grid", gap: 2 }}>
      <span style={{
        fontSize: 10,
        color: missing ? "#b45309" : "var(--muted)",
        textTransform: "uppercase",
        letterSpacing: 0.5,
      }}>
        {label}{missing && " · missing"}
      </span>
      <input
        type={type}
        value={value ?? ""}
        onChange={(e) => onChange(e.target.value || null)}
        placeholder={missing ? `Add ${label.toLowerCase()}…` : undefined}

