/**
 * Every alias on this site, optionally restricted to a single HSN
 * bucket. Used by the bill matcher's fuzzy step so that an OCR'd line
 * like "TATA SALT 1Kg IODISED" can hit an admin-validated alias
 * "TATA SALT 1KG IODIZED" even though the two strings aren't byte-
 * identical (different casing, missing letter, etc.). The HSN-scoped
 * call is preferred — it scales with bucket size rather than the whole
 * catalog. The unscoped variant is the global-fallback fuzzy.
 *
 * Catalog and alias counts at any single site are small (low thousands
 * at most), so we don't bother with an index or pagination — Postgres
 * will sequential-scan with a HASH JOIN at this scale and still be
 * sub-millisecond.
 */
export async function listProductAliasesForSite(
  siteId: string,
  hsnCode?: string | null,
): Promise<ProductAlias[]> {
  const db = await getDb();
  if (hsnCode) {
    const result = await db.execute({
      sql: `SELECT * FROM product_aliases WHERE site_id = ? AND hsn_code = ?`,
      args: [siteId, hsnCode],
    });
    return result.rows as ProductAlias[];
  }
  const result = await db.execute({
    sql: `SELECT * FROM product_aliases WHERE site_id = ?`,
    args: [siteId],
  });
  return result.rows as ProductAlias[];
}

