export type Suggestion = {
  productId: string;
  canonicalName: string;
  unit: string;
  packSize: number;
  hsnCode: string | null;
  category: string | null;
  score: number;
  method: "exact" | "alias" | "alias_fuzzy" | "hsn_fuzzy" | "normalized" | "global_fuzzy";
};

/**
 * Run alias-fuzzy: compare the bill line name against every learned
 * alias' raw_name and surface the highest-scoring product. HSN-scoped
 * when available so an alias for "Toor Dal" under HSN 0713 doesn't
 * compete with "Toor Dal Snack Pack" under a different HSN.
 *
 * Returns at most one candidate per product_id (multiple aliases for
 * the same product are normal — we keep the best-scoring one). Below
 * threshold = no candidate, the caller falls through to the next step.
 */
async function bestAliasFuzzyMatch(
  siteId: string,
  rawName: string,
  hsn: string | null,
  threshold: number,
): Promise<{ alias: ProductAlias; product: CanonicalProduct; score: number } | null> {
  const aliases = await listProductAliasesForSite(siteId, hsn);
  if (aliases.length === 0) return null;

  // Group by product_id, keep best-scoring alias per product.
  type Best = { alias: ProductAlias; score: number };
  const bestByProduct = new Map<string, Best>();
  for (const a of aliases) {
    const score = fuzzyScore(rawName, a.raw_name);
    if (score < threshold) continue;
    const cur = bestByProduct.get(a.product_id);
    if (!cur || score > cur.score) bestByProduct.set(a.product_id, { alias: a, score });
  }
  if (bestByProduct.size === 0) return null;

  // Pick the overall winner.
  let winner: { productId: string; alias: ProductAlias; score: number } | null = null;
  for (const [productId, b] of bestByProduct) {
    if (!winner || b.score > winner.score) winner = { productId, alias: b.alias, score: b.score };
  }
  if (!winner) return null;

  const product = await findCanonicalProduct(winner.productId);
  if (!product) return null;
  return { alias: winner.alias, product, score: winner.score };
}

