// Step 2: Product alias cache hit (HSN-aware, exact raw_name match)
const alias = await findProductAlias(siteId, name, hsn);
if (alias && alias.confidence >= 0.7) {
  return {
    matched: true,
    productId: alias.product_id,
    canonicalName: alias.raw_name,
    confidence: alias.confidence,
    method: "alias",
  };
}

// Step 2.5: Alias-fuzzy. The OCR'd name often differs slightly from
// the exact alias an admin previously validated; compare against
// every learned alias's raw_name so we still catch the mapping.
// 0.75 threshold here (higher than the 0.6 we use for suggestions)
// because auto-matching writes an order line — we want to avoid the
// "wrong mapping committed silently" failure mode that motivated
// separating "auto-match" from "suggest" in the first place.
let aliasFuzzy = await bestAliasFuzzyMatch(siteId, name, hsn, 0.75);
if (!aliasFuzzy && hsn) {
  aliasFuzzy = await bestAliasFuzzyMatch(siteId, name, null, 0.75);
}
if (aliasFuzzy) {
  // Learn the exact (post-OCR-jitter) name too so the next pass hits
  // the cheap exact-alias path on Step 2 without re-running fuzzy.
  await saveProductAlias({
    id: `pa_${nanoid(12)}`,
    siteId,
    rawName: name,
    productId: aliasFuzzy.product.product_id,
    hsnCode: hsn,
    confidence: aliasFuzzy.score * ALIAS_FUZZY_SCORE_DISCOUNT,
    source: "alias_fuzzy",
  });
  return {
    matched: true,
    productId: aliasFuzzy.product.product_id,
    canonicalName: aliasFuzzy.product.canonical_name,
    confidence: aliasFuzzy.score * ALIAS_FUZZY_SCORE_DISCOUNT,
    method: "alias_fuzzy",
  };
}

