1	/**
2	 * Office Operations Intelligence — Server Entry Point
3	 *
4	 * THIN BOOTSTRAP: This file only initializes channels, registers
5	 * them with the core, and starts the scheduler. All business logic
6	 * lives in core/ and channels/ modules.
7	 *
8	 * Architecture:
9	 *   channels/telegram/  → Receives messages, translates to StandardMessage
10	 *   core/message-router  → Routes StandardMessage to workflows/agents
11	 *   core/scheduler       → Runs periodic tasks (daily summary, overdue checks)
12	 *   channels/index       → Registry mapping channel names to adapters
13	 *
14	 * Run with: bun run dev (uses Mastra dev server)
15	 * Or directly: bun run src/mastra/server.ts (standalone)
16	 */
17	
18	import type TelegramBot from "node-telegram-bot-api";
