76	
77	const VISITOR_HTTP_CORS_HEADERS = {
78	  'Access-Control-Allow-Origin': '*',
79	  'Access-Control-Allow-Methods': 'GET,POST,PUT,PATCH,DELETE,OPTIONS',
80	  'Access-Control-Allow-Headers': [
81	    'Content-Type',
82	    'Accept',
83	    'Authorization',
84	    'x-admin-secret',
85	    'x-actor-name',
86	    'x-actor-email',
