/**
 * Office Operations Intelligence — Server Entry Point
 *
 * THIN BOOTSTRAP: This file only initializes channels, registers
 * them with the core, and starts the scheduler. All business logic
 * lives in core/ and channels/ modules.
 *
 * Architecture:
 *   channels/telegram/  → Receives messages, translates to StandardMessage
 *   core/message-router  → Routes StandardMessage to workflows/agents
 *   core/scheduler       → Runs periodic tasks (daily summary, overdue checks)
 *   channels/index       → Registry mapping channel names to adapters
 *
 * Run with: bun run dev (uses Mastra dev server)
 * Or directly: bun run src/mastra/server.ts (standalone)
 */

import type TelegramBot from "node-telegram-bot-api";
import type { ChannelAdapter, SendMessageOptions } from "./core/types";
import {
  createServer as createHttpServer,
  type IncomingMessage,
  type ServerResponse,
} from "http";

// ─── Core ─────────────────────────────────────────────────
import { handleMessage, registerChannelConfig } from "./core/message-router";
import { setupScheduledTasks } from "./core/scheduler";
import {
  registerChannel,
  registerMediaDownloader,
  handleChannelHttpRequest,
} from "./channels/index";
import { whatsappAdapter, isWhatsAppConfigured } from "./channels/whatsapp";

// ─── Telegram Channel ────────────────────────────────────
import {
  getBot,
  startBotPolling,
  setupWebhook,
  registerBotCommands,
  isGroupMessage,
  isPrivateMessage,
  getMessageText,
  getSenderName,
} from "./channels/telegram/bot";
import { sendMessage } from "./channels/telegram/sender";
import { toStandardMessage } from "./channels/telegram/adapter";
import { ingestGroupMessage } from "./channels/telegram/buffer";
import { handleCommand, isWhereAmICommand, replyWithChatDetails } from "./channels/telegram/commands";
import { registerCallbackHandler } from "./channels/telegram/callbacks";
import { telegramMediaDownloader } from "./channels/telegram/media";

// ─── Logger ───────────────────────────────────────────────
import {
  installConsoleBridge,
  logError,
  logHttpRequest,
  logHttpResponse,
  logInfo,
  logWarn,
  newRequestId,
  withLogContext,
  type LogContext,
} from "./lib/logger";
import { telegram as tgConfig } from "./lib/config";
import { getPostgresPool } from "./lib/postgres";

import {
  isOfflineSyncText,
  parseOfflineSyncText,
  processOfflineSyncEvent,
} from "./plugins/visitor";
import { handlePluginHttpRequest, initPlugins } from "./plugins";
import { ensureSeedGraphs } from "./lib/graph";

const VISITOR_HTTP_CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,POST,PUT,PATCH,DELETE,OPTIONS',
  'Access-Control-Allow-Headers': [
    'Content-Type',
    'Accept',
    'Authorization',
    'x-admin-secret',
    'x-actor-name',
    'x-actor-email',
    'x-actor-role',
    'x-guard-token',
    'x-site-id',
    'x-device-id',
    'x-invited-by',
    'ngrok-skip-browser-warning',
  ].join(','),
  'Access-Control-Max-Age': '86400',
} as const;

// ─── Helpers ──────────────────────────────────────────────

function envFlag(value: string | undefined): boolean | undefined {
  if (value === undefined) return undefined;
  const normalized = value.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return undefined;
}

function shouldStartTelegramChannel(): boolean {
  const explicit = envFlag(process.env.TELEGRAM_ENABLED);
  if (explicit === false) return false;
  if (explicit === true && !process.env.TELEGRAM_BOT_TOKEN) {
    throw new Error("TELEGRAM_ENABLED=true requires TELEGRAM_BOT_TOKEN.");
  }
  return Boolean(process.env.TELEGRAM_BOT_TOKEN);
}

function getRequestPathname(req: IncomingMessage): string {
  try {
    return new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`).pathname;
  } catch {
    return req.url?.split("?")[0] ?? "/";
  }
}

function getRequestQuery(req: IncomingMessage): string {
  try {
    return new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`).search.replace(/^\?/, "");
  } catch {
    const q = req.url?.split("?")[1];
    return q ?? "";
  }
}

function getClientIp(req: IncomingMessage): string | undefined {
  const fwd = req.headers["x-forwarded-for"];
  if (typeof fwd === "string" && fwd.length > 0) return fwd.split(",")[0]?.trim();
  if (Array.isArray(fwd) && fwd.length > 0) return fwd[0];
  return req.socket?.remoteAddress ?? undefined;
}

// Paths excluded from per-request terminal logging. Health/readiness probes
// from orchestrators hit constantly and would drown out actual API traffic.
const HTTP_LOG_SKIP_PATHS = new Set(["/health", "/ready", "/favicon.ico"]);

function shouldLogHttp(method: string | undefined, path: string): boolean {
  if (HTTP_LOG_SKIP_PATHS.has(path)) return false;
  if (method === "OPTIONS") return false; // CORS preflight noise
  return true;
}

function jsonResponse(
  res: ServerResponse,
  status: number,
  body: Record<string, unknown>,
): void {
  res.writeHead(status, {
    ...VISITOR_HTTP_CORS_HEADERS,
    "Content-Type": "application/json",
  });
  res.end(JSON.stringify(body));
}

async function handleHealthRequest(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<boolean> {
  if (req.method !== "GET" && req.method !== "HEAD") return false;

  const pathname = getRequestPathname(req);
  if (pathname === "/health") {
    jsonResponse(res, 200, {
      ok: true,
      service: "appointy-ops-backend",
      timestamp: new Date().toISOString(),
    });
    return true;
  }

  if (pathname === "/ready") {
    try {
      await getPostgresPool().query("select 1");
      jsonResponse(res, 200, {
        ok: true,
        database: "reachable",
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      jsonResponse(res, 503, {
        ok: false,
        database: "unreachable",
        error: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString(),
      });
    }
    return true;
  }

  return false;
}

function buildMessageLogContext(
  scope: string,
  msg: TelegramBot.Message,
): LogContext {
  return {
    scope,
    eventId: `${msg.chat.id}:${msg.message_id}`,
    chatId: msg.chat.id,
    userId: msg.from?.id,
    messageId: msg.message_id,
  };
}

function isVisitorManagementGroup(chatId: number): boolean {
  return tgConfig.visitorGroupIds().includes(chatId);
}

// ─── Telegram Channel Adapter ─────────────────────────────
// Implements ChannelAdapter interface for the registry.

const telegramAdapter: ChannelAdapter = {
  name: "telegram",

  async initialize(): Promise<void> {
    // Bot initialization is handled in startTelegramChannel()
  },

  async shutdown(): Promise<void> {
    const bot = getBot();
    try {
      await bot.stopPolling();
      logInfo("Telegram polling stopped", { scope: "telegram" });
    } catch {
      // ignore
    }
  },

  async sendMessage(chatId: string, text: string, options?: SendMessageOptions): Promise<void> {
    const parseMode = options?.parseMode === "markdown" ? "Markdown" as const
      : options?.parseMode === "html" ? "HTML" as const
      : undefined;
    await sendMessage(Number(chatId), text, {
      parseMode,
      replyToMessageId: options?.replyToMessageId ? Number(options.replyToMessageId) : undefined,
    });
  },

  async notifyAdmins(text: string, options?: SendMessageOptions): Promise<void> {
    const adminIds = tgConfig.adminIds();
    const parseMode = options?.parseMode === "markdown" ? "Markdown" as const
      : options?.parseMode === "html" ? "HTML" as const
      : undefined;

    for (const adminId of adminIds) {
      try {
        await sendMessage(adminId, text, { parseMode });
      } catch (error) {
        logWarn(`Failed to notify Telegram admin ${adminId}: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
  },
};

// ─── Start Telegram Channel ──────────────────────────────

async function startTelegramChannel(): Promise<void> {
  const bot = getBot();

  // ─── Graceful Shutdown ───────────────────────────────────
  let shuttingDown = false;
  const shutdown = async () => {
    if (shuttingDown) return;
    shuttingDown = true;
    logInfo("Shutting down bot", { scope: "server" });
    await telegramAdapter.shutdown();
    setTimeout(() => process.exit(0), 3000).unref();
    process.exit(0);
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
  process.on("SIGHUP", shutdown);
  process.on("beforeExit", shutdown);

  // ─── Polling Error Handler ──────────────────────────────
  bot.on("polling_error", (error: any) => {
    logError("Telegram polling error", error?.message || error, {
      scope: "telegram.polling",
    });
    if (error?.message?.includes("409")) {
      logError(
        "Another bot instance is running. Stop the duplicate process and restart.",
        undefined,
        { scope: "telegram.polling" },
      );
    }
  });

  // ─── Raw Update Diagnostics ─────────────────────────────
  (bot as any).on("update", (update: any) => {
    const type =
      Object.keys(update)
        .filter((k) => k !== "update_id")
        .join(", ") || "unknown";
    const id = update.update_id;
    if (update.callback_query) {
      const cb = update.callback_query;
      logInfo(
        `Telegram update received: callback_query data="${cb.data}" from=${cb.from?.first_name} (${cb.from?.id}) msg_id=${cb.message?.message_id}`,
        {
          scope: "telegram.update",
          eventId: String(id),
          chatId: cb.message?.chat?.id,
          userId: cb.from?.id,
          messageId: cb.message?.message_id,
          action: cb.data,
        },
      );
    } else {
      logInfo(`Telegram update received: ${type}`, {
        scope: "telegram.update",
        eventId: String(id),
      });
    }
  });

  await registerBotCommands();

  // ─── Message Handler ────────────────────────────────────
  // Translates Telegram messages to StandardMessage and routes to core.
  bot.on("message", async (msg: TelegramBot.Message) => {
    try {
      const scope = isPrivateMessage(msg)
        ? "telegram.dm"
        : isGroupMessage(msg)
          ? "telegram.group"
          : "telegram.message";
      await withLogContext(buildMessageLogContext(scope, msg), async () => {
        // Skip bot's own messages
        if (msg.from?.is_bot) return;

        if (isWhereAmICommand(getMessageText(msg))) {
          await replyWithChatDetails(msg);
          return;
        }

        if (isGroupMessage(msg)) {
          if (isVisitorManagementGroup(msg.chat.id)) {
            logInfo("Ignoring inbound message from visitor management broadcast group", {
              scope: "telegram.group.visitor-management",
              chatId: msg.chat.id,
              userId: msg.from?.id,
              messageId: msg.message_id,
            });
            return;
          }

          const text = getMessageText(msg);
          if (isOfflineSyncText(text)) {
            try {
              const offlineEvent = parseOfflineSyncText(text ?? "");
              const result = await processOfflineSyncEvent({
                event: offlineEvent,
                source: "telegram",
                backupText: text ?? undefined,
                sourceChannel: "telegram",
                sourceChatId: String(msg.chat.id),
                sourceMessageId: String(msg.message_id),
              });

              logInfo(
                `[OfflineSync] Telegram backup processed: ${result.offlineEventId} -> ${result.status}`,
                {
                  scope: "telegram.offline-sync",
                  chatId: msg.chat.id,
                  userId: msg.from?.id,
                  messageId: msg.message_id,
                },
              );
            } catch (offlineError) {
              logWarn(
                `Failed to parse/process Telegram offline backup: ${offlineError instanceof Error ? offlineError.message : String(offlineError)}`,
              );
              await ingestGroupMessage(msg);
            }
            return;
          }

          // Ingest immediately to DB — batch processor handles grouping
          await ingestGroupMessage(msg);
        } else if (isPrivateMessage(msg)) {
          // Private messages go directly to core
          const standardMsg = toStandardMessage(msg);

          // Fire `telegram.message_received` so admins can wire automations
          // to Telegram bot messages. Runs in parallel — failures swallowed.
          try {
            const { runFlowRules } = await import("./lib/flow");
            await runFlowRules("telegram", "telegram.message_received", {
              text: getMessageText(msg) ?? "",
              intent: undefined,
              actor: {
                name: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(" "),
                telegramUserId: String(msg.from?.id ?? ""),
              },
              chatRef: String(msg.chat.id),
              _meta: {
                originChannel: "telegram",
                telegramChatId: msg.chat.id,
                telegramMessageId: msg.message_id,
              },
            });
          } catch (err) {
            logWarn(
              `telegram.message_received flow dispatch failed: ${err instanceof Error ? err.message : String(err)}`,
            );
          }

          await handleMessage(standardMsg);
        }
      });
    } catch (error) {
      logError("Message handler error", error, {
        scope: "telegram.message",
        chatId: msg.chat.id,
        userId: msg.from?.id,
        messageId: msg.message_id,
      });
    }
  });

  bot.on("channel_post", async (msg: TelegramBot.Message) => {
    try {
      await withLogContext(
        buildMessageLogContext("telegram.channel", msg),
        async () => {
          if (isWhereAmICommand(getMessageText(msg))) {
            await replyWithChatDetails(msg);
          }
        },
      );
    } catch (error) {
      logError("Channel post handler error", error, {
        scope: "telegram.channel",
        chatId: msg.chat.id,
        messageId: msg.message_id,
      });
    }
  });

  // ─── Register Callback Handlers (inline buttons) ───────
  registerCallbackHandler();

  // ─── Webhook or Polling (AFTER all handlers) ───────────
  // setupWebhook() registers the URL with Telegram when TELEGRAM_WEBHOOK_URL is set.
  // startBotPolling() is a no-op when webhook mode is active.
  await setupWebhook();
  await startBotPolling();
}

// ─── Initialize ───────────────────────────────────────────

async function startServer() {
  installConsoleBridge();
  logInfo("Starting Office Operations Intelligence", { scope: "server" });
  logInfo("Architecture: Central Intelligence + Connectors", {
    scope: "server",
  });
  logInfo(
    "Tunnel shortcut available via: npm run tunnel (exposes localhost:4111 via srv.us)",
    { scope: "server.dev" },
  );

  // ─── Register Channels ─────────────────────────────────
  // Each channel registers itself with the core registry.
  // Adding a new channel is as simple as:
  //   1. Create channels/<name>/adapter.ts
  //   2. Register it here

  const telegramEnabled = shouldStartTelegramChannel();
  if (telegramEnabled) {
    registerChannel(telegramAdapter);
    registerMediaDownloader("telegram", telegramMediaDownloader);

    // Register Telegram-specific config with the core message router
    registerChannelConfig("telegram", {
      onCommand: async (message, command, args) => {
        // Retrieve the raw Telegram message from the StandardMessage payload
        const rawMsg = message.rawPayload as TelegramBot.Message;
        if (rawMsg) {
          await handleCommand(rawMsg, `${command} ${args.join(" ")}`.trim());
        }
      },
      onReply: async (chatId, text, options) => {
        const parseMode = options?.parseMode === "markdown" ? "Markdown" as const
          : options?.parseMode === "html" ? "HTML" as const
          : undefined;
        await sendMessage(Number(chatId), text, { parseMode });
      },
      onTyping: async (chatId) => {
        const bot = getBot();
        await bot.sendChatAction(Number(chatId), "typing");
      },
    });

    // ─── Start Telegram ────────────────────────────────────
    await startTelegramChannel();
  } else {
    logWarn("Telegram channel disabled. Set TELEGRAM_ENABLED=true and TELEGRAM_BOT_TOKEN to enable it.", {
      scope: "server",
    });
  }

  // ─── Register WhatsApp Channel ───────────────────────────
  // Drop-in: the adapter declares its own webhook routes, so we
  // only register it. No route mounting needed here.
  if (isWhatsAppConfigured()) {
    registerChannel(whatsappAdapter);
    await whatsappAdapter.initialize();
    logInfo("WhatsApp channel registered (webhook at POST/GET /webhook/whatsapp)", {
      scope: "server",
    });
  } else {
    logWarn(
      "WhatsApp channel disabled. Set WHATSAPP_ACCESS_TOKEN, WHATSAPP_PHONE_NUMBER_ID, and WHATSAPP_VERIFY_TOKEN to enable it.",
      { scope: "server" },
    );
  }

  // ─── Initialize System Plugins ───────────────────────────
  await initPlugins();

  // ─── Seed System Flow Graphs ────────────────────────────
  try {
    await ensureSeedGraphs();
    logInfo("System flow graphs seeded", { scope: "server" });
  } catch (err) {
    logWarn(`Failed to seed flow graphs: ${err instanceof Error ? err.message : String(err)}`, { scope: "server" });
  }

  // ─── Start Visitor HTTP Server ────────────────────────────
  const visitorPort = Number(process.env.VISITOR_HTTP_PORT ?? 4112);
  const httpServer = createHttpServer(async (req, res) => {
    const method = req.method ?? "GET";
    const path = getRequestPathname(req);
    const query = getRequestQuery(req);
    const ip = getClientIp(req);
    const reqId = newRequestId();
    const startedAt = Date.now();
    const shouldLog = shouldLogHttp(method, path);

    if (shouldLog) {
      logHttpRequest({ method, path, query: query || undefined, ip, reqId });
    }

    let responseLogged = false;
    const logResponseOnce = () => {
      if (responseLogged || !shouldLog) return;
      responseLogged = true;
      logHttpResponse({
        method,
        path,
        status: res.statusCode,
        durationMs: Date.now() - startedAt,
        reqId,
      });
    };
    res.on("finish", logResponseOnce);
    res.on("close", logResponseOnce);

    await withLogContext({ scope: "http", reqId }, async () => {
      if (method === "OPTIONS") {
        res.writeHead(204, {
          ...VISITOR_HTTP_CORS_HEADERS,
        });
        res.end();
        return;
      }
      if (await handleHealthRequest(req, res)) {
        return;
      }
      try {
        // Channel-declared routes (webhooks) take priority — each
        // ChannelAdapter publishes its own routes() so the server
        // mounts them automatically. Add a channel; it just works.
        if (await handleChannelHttpRequest(req, res)) {
          return;
        }
        const handled = await handlePluginHttpRequest(req, res);
        if (!handled) {
          res.writeHead(404, {
            ...VISITOR_HTTP_CORS_HEADERS,
            'Content-Type': 'text/plain',
          });
          res.end('Not found');
        }
      } catch (error) {
        logError('Visitor HTTP handler error', error, { scope: 'visitor.http', reqId });
        if (!res.headersSent) {
          res.writeHead(500, {
            ...VISITOR_HTTP_CORS_HEADERS,
            'Content-Type': 'application/json',
          });
          res.end(JSON.stringify({ error: 'Internal server error' }));
        }
      }
    });
  });

  httpServer.listen(visitorPort, () => {
    logInfo(`Visitor HTTP server on :${visitorPort}`, { scope: 'visitor.http' });
    logInfo(`Visitor and ops dashboard frontends should call API origin http://localhost:${visitorPort}`, { scope: 'visitor.http' });
  });

  // ─── Start Scheduler (platform-agnostic) ───────────────
  await setupScheduledTasks();

  logInfo("Server is running — all channels active", { scope: "server" });
}

// ─── Start ────────────────────────────────────────────────

startServer().catch((error) => {
  logError("Failed to start server", error, { scope: "server" });
  process.exit(1);
});

